fn list_classes(
    (InMut(ui), InMut(tab)): (InMut<Ui>, InMut<ClassesTab>),
    mut class_q: Query<(Entity, &Class, &Name, &mut DisplayedStroke)>,
    entity_name_q: Query<(Entity, &Name)>,
