                    return;
                };
                let Ok((_, class, _, _)) = class_q.get(class_entity) else {
                    return;
                };
                let mut hovered = false;
                ui.with_layout(Layout::default().with_cross_justify(true), |ui| {
                    for (trip_entity, name) in
                        entity_name_q.iter_many(class.as_trips().iter().copied())
