                    let printed = itoa_buffer.format(class.as_trips().len());
                    ui.label(printed);
                    ui.add(&mut stroke.color);
                    ui.end_row();
                }
            });
    });

    ScrollArea::vertical().id_salt("third").show(ui, |ui| {
        let Some(trip_entity) = tab.hovered_trip else {
            return;
        };
        ui.label(trip_entity.to_string());
    });
