                world
                    .run_system_cached_with(
                        display_station_info,
                        (
                            ui,
                            stations.as_slice(),
                            &mut self.highlight_station_intervals,
                        ),
                    )
                    .unwrap();
            }
            SelectedItems::ExtendingRoute(r) => {}
        }
    }
}

fn display_station_info(
    (InMut(ui), InRef(selected_stations), InMut(highlight_station_intervals)): (
        InMut<Ui>,
        InRef<[StationSelection]>,
        InMut<Vec<Entity>>,
    ),
    station_q: Query<StationQuery>,
    interval_q: Query<IntervalQuery>,
    graph: Res<Graph>,
    mut commands: Commands,
    mut last_hovered: Local<bool>,
) {
    for station in station_q.iter_many(selected_stations.iter().map(|it| it.station)) {
        ui.label(station.name.as_ref());
    }
    let res = ui.button(tr!("graph-create-new-route"));
    if selected_stations.len() < 2 {
        *last_hovered = res.hovered();
        return;
    }
    let selected_station_entities_iter = selected_stations.iter().map(|it| it.station);
    if res.hovered() ^ *last_hovered
        && let Some((_, points)) =
            graph.route_between_source_waypoint_target(selected_station_entities_iter, &interval_q)
    {
        // refresh
        highlight_station_intervals.clear();
        highlight_station_intervals.extend_from_slice(&points);
    } else if !res.hovered() {
        highlight_station_intervals.clear()
    }
    if res.clicked() {
        commands.spawn((
            Name::new("New Route"),
            Route {
                lengths: vec![10.0; highlight_station_intervals.len()],
                stops: highlight_station_intervals.clone(),
            },
        ));
    }
    *last_hovered = res.hovered();
}

fn display(tab: &mut GraphTab, world: &mut World, ui: &mut egui::Ui) {
    // allocate painter for drawing afterwards
    let (response, mut painter) =
        ui.allocate_painter(ui.available_size_before_wrap(), Sense::click_and_drag());
    tab.navi.visible = response.rect;
    tab.navi.handle_navigation(ui, &response);

    // fetch attribution info to draw later
    let attribution = world
        .run_system_cached_with(
            underlay::draw_underlay,
            (&mut painter, &tab.navi, ui, tab.underlay_tile_change),
        )
        .unwrap();

    let mut state = tab.gpu_state.lock();
    if let Some(target_format) = ui.data(|data| {
        data.get_temp::<eframe::egui_wgpu::wgpu::TextureFormat>(egui::Id::new("wgpu_target_format"))
    }) {
        state.target_format = Some(target_format);
    }
    if let Some(msaa_samples) =
        ui.data(|data| data.get_temp::<u32>(egui::Id::new("wgpu_msaa_samples")))
    {
        state.msaa_samples = msaa_samples;
    }

    let interact_pos = response
        .clicked()
        .then_some(ui.input(|r| r.pointer.interact_pos()))
        .flatten();

    // push draw items and handle selection
    let selected_item = world
        .run_system_cached_with(
            push_draw_items,
            (
                ui.visuals().dark_mode,
                &tab.navi,
                &mut state.instances,
                &mut painter,
                interact_pos,
                ui.animate_bool(ui.id().with("gugugaga"), tab.navi.zoom > 0.002),
            ),
        )
        .unwrap();

    let shift_pressed = ui.input(|r| r.modifiers.shift);
    match (
        selected_item.clone(),
        ui.input(|r| r.modifiers.command),
        shift_pressed,
    ) {
        (Some(Some(selected_item)), true, _) => {
            world.write_message(ModifySelectedItems::Toggle(selected_item));
        }
        (Some(Some(selected_item)), false, _) => {
            world.write_message(ModifySelectedItems::SetSingle(selected_item));
        }
        (Some(None), true, _) => {
            // do nothing in this case.
        }
        (Some(None), false, true) => {
            // also do nothing in this case.
        }
        (Some(None), false, false) => {
            world.write_message(ModifySelectedItems::Clear);
        }
        (None, _, _) => {
            // do nothing in this case. No interactions, no response
        }
    }

    let callback = gpu_draw::paint_callback(response.rect, tab.gpu_state.clone());
    painter.add(callback);

    // draw the attribution and the scale bar
    if let Some(attribution) = attribution {
        draw_attribution(ui, response.rect, &attribution);
    }
    draw_scale_bar(
        &painter,
        response.rect,
        tab.navi.zoom,
        ui.visuals().text_color(),
    );

    world.resource_scope(|world, mut selected_items: Mut<SelectedItems>| {
        let state: GraphState<'_> = selected_items.as_mut().into();
        let interact_pos = response
            .clicked()
            .then(|| ui.input(|r| r.pointer.interact_pos()))
            .flatten();

        let mut display_station_info = |ui: &mut Ui, station_entity: Entity| {
            let coor = world.get::<Node>(station_entity).unwrap().coor;
            let (x, y) = coor.to_xy();
            let pos = tab.navi.xy_to_screen_pos(x, y);
            let rect = Rect::from_pos(pos).expand(8.0);
            let res = ui
                .allocate_rect(rect, Sense::drag())
                .on_hover_cursor(CursorIcon::Grab);
            if res.dragged() {
                ui.set_cursor_icon(egui::CursorIcon::Grabbing);
                let new_pos = pos + res.drag_delta();
                let (x, y) = tab.navi.screen_pos_to_xy(new_pos);
                let new_coor = NodeCoor::from_xy(x, y);
                world.get_mut::<Node>(station_entity).unwrap().coor = new_coor;
            }
            Popup::menu(&res)
                .open(true)
                .close_behavior(PopupCloseBehavior::CloseOnClickOutside)
                .show(|ui| {
                    ui.set_width(150.0);
                    ui.horizontal(|ui| {
                        world.get_mut::<Name>(station_entity).unwrap().mutate(|s| {
                            ui.text_edit_singleline(s);
                        });
                        if ui.button("A").clicked() {
                            world
                                .commands()
                                .entity(station_entity)
                                .insert(StationNamePending::new(coor));
                        }
                    });
                    ui.small(coor.to_string());
                });
        };

        match state {
            GraphState::Idle if let Some(Some(_selected_item)) = selected_item => {
                // TODO: merge this block with the previous block
            }
            GraphState::Idle if let Some(interact_pos) = interact_pos => {
                let (x, y) = tab.navi.screen_pos_to_xy(interact_pos);
                let coor = NodeCoor::from_xy(x, y);
                world
                    .commands()
                    .write_message(ModifySelectedItems::SetSingle(SelectedItem::Coordinate(
                        CoordinateSelection {
                            coor,
                            name_candidate: String::new(),
                        },
                    )));
            }
            GraphState::Idle => {}
            GraphState::SelectingCoordinate(CoordinateSelection {
                coor,
                name_candidate,
            }) => {
                let pos = coor.to_xy();
                let screen_pos = tab.navi.xy_to_screen_pos(pos.0, pos.1);
                let rect = Rect::from_pos(screen_pos).expand(6.0);
                painter.rect(
                    rect,
                    0,
                    Color32::RED.gamma_multiply(0.5),
                    Stroke::new(1.0, Color32::RED),
                    egui::StrokeKind::Middle,
                );
                let res = ui
                    .allocate_rect(rect, Sense::drag())
                    .on_hover_cursor(egui::CursorIcon::Grab);
                if res.dragged() {
                    ui.set_cursor_icon(egui::CursorIcon::Grabbing);
                    let new_screen_pos = screen_pos + res.drag_delta();
                    let (x, y) = tab.navi.screen_pos_to_xy(new_screen_pos);
                    *coor = NodeCoor::from_xy(x, y);
                }

                Popup::menu(&res)
                    .open(true)
                    .close_behavior(PopupCloseBehavior::CloseOnClickOutside)
                    .show(|ui| {
                        ui.set_width(200.0);
                        ui.text_edit_singleline(name_candidate);
                        let coor = NodeCoor::from_xy(pos.0, pos.1);
                        if ui.button(tr!("graph-new-station")).clicked() {
                            let name = (!name_candidate.is_empty()).then(|| name_candidate.clone());
                            world.trigger(CreateNewStation { name, coor });
                            world.commands().write_message(ModifySelectedItems::Clear);
                        }
                        ui.small(coor.to_string());
                    });

                if selected_item.is_some() {
                    world.commands().write_message(ModifySelectedItems::Clear);
                }
            }
            GraphState::SelectingTrips(it) => {
                // TODO
            }
            GraphState::SelectingIntervals(it) => {
                // TODO
            }
            GraphState::SelectingStations(stations) => {
                for station in stations {
                    display_station_info(ui, station.station);
                }
            }
            GraphState::SelectingStation(station) => {
                display_station_info(ui, station.station);
                // check if shift is down
                if shift_pressed && let Some(cursor_pos) = ui.input(|r| r.pointer.hover_pos()) {
                    let coor = world.get::<Node>(station.station).unwrap().coor;
                    let (x, y) = coor.to_xy();
                    let station_pos = tab.navi.xy_to_screen_pos(x, y);
                    painter.line_segment([station_pos, cursor_pos], Stroke::new(1.0, Color32::RED));
                    if let Some(Some(SelectedItem::Station(selected))) = selected_item {
                        world.trigger(AddIntervalPair {
                            source: station.station,
                            target: selected.station,
                            length: Distance::from_m(1000),
                        });
                    }
                }
            }
        }
    });
}

fn draw_scale_bar(painter: &Painter, viewport: Rect, zoom: f32, color: egui::Color32) {
    if zoom <= 0.0 || !viewport.is_positive() {
        return;
    }

    let desired_px = 120.0f64;
    let meters_per_px = 1.0 / zoom as f64;
    let raw_meters = desired_px * meters_per_px;
    let bar_meters = round_to_1_2_5(raw_meters).max(1.0);
    let bar_px = (bar_meters as f32 * zoom).max(1.0);

    let margin = 10.0;
    let baseline_y = viewport.bottom() - margin;
    let left_x = viewport.left() + margin;
    let right_x = left_x + bar_px;

    let stroke = Stroke::new(1.6, color);
    painter.line_segment(
        [
            Pos2::new(left_x, baseline_y),
            Pos2::new(right_x, baseline_y),
        ],
        stroke,
    );

    let tick_len = 7.0;
    painter.line_segment(
        [
            Pos2::new(left_x, baseline_y),
            Pos2::new(left_x, baseline_y - tick_len),
        ],
        stroke,
    );
    painter.line_segment(
        [
            Pos2::new(right_x, baseline_y),
            Pos2::new(right_x, baseline_y - tick_len),
        ],
        stroke,
    );

    let mid_tick_len = 5.0;
    for fraction in [0.25f32, 0.5, 0.75] {
        let x = left_x + bar_px * fraction;
        painter.line_segment(
            [
                Pos2::new(x, baseline_y),
                Pos2::new(x, baseline_y - mid_tick_len),
            ],
            stroke,
        );
    }

    painter.text(
        Pos2::new(left_x, baseline_y - tick_len - 3.0),
        Align2::LEFT_BOTTOM,
        format_scale_label(bar_meters),
        FontId::proportional(12.0),
        color,
    );
}

fn round_to_1_2_5(value: f64) -> f64 {
    if value <= 0.0 {
        return 0.0;
    }
    let exponent = value.log10().floor();
    let base = 10.0f64.powf(exponent);
    let normalized = value / base;
    let rounded = if normalized <= 1.0 {
        1.0
    } else if normalized <= 2.0 {
        2.0
    } else if normalized <= 5.0 {
        5.0
    } else {
        10.0
    };
    rounded * base
}

fn format_scale_label(meters: f64) -> String {
    if meters >= 1000.0 {
        let km = meters / 1000.0;
        if (km - km.round()).abs() < 1e-6 {
            format!("{:.0} km", km)
        } else {
            format!("{:.1} km", km)
        }
    } else {
        format!("{:.0} m", meters)
    }
}

fn draw_attribution(ui: &mut Ui, viewport: Rect, attribution: &Attribution) {
    let margin = 6.0;
    let font_id = FontId::proportional(13.0);
    let color = ui.style().visuals.hyperlink_color;
    let text = format!("© {}", attribution.text);
    let galley = ui.painter().layout_no_wrap(text.clone(), font_id, color);
    let size = galley.size();
    let min = Pos2::new(
        viewport.right() - margin - size.x,
        viewport.bottom() - margin - size.y,
    );
    let rect = Rect::from_min_size(min, size);
    let mut r = CornerRadius::ZERO;
    r.nw = 4;
    ui.painter()
        .rect_filled(rect.expand(margin), r, Color32::WHITE.gamma_multiply(0.5));
    ui.put(
        rect,
        egui::Hyperlink::from_label_and_url(text, attribution.url).open_in_new_tab(true),
    );
}

fn push_draw_items(
    (
        In(is_dark),
        InRef(navi),
        InMut(buffer),
        InMut(painter),
        In(maybe_interact_pos),
        In(text_strength),
    ): (
        In<bool>,
        InRef<GraphNavigation>,
        InMut<Vec<ShapeInstance>>,
        InMut<Painter>,
        In<Option<Pos2>>,
        In<f32>,
    ),
    nodes: Query<(Entity, &Node, Option<&Name>)>,
    spatial_index: Res<GraphSpatialIndex>,
    interval_spatial_index: Res<GraphIntervalSpatialIndex>,
    trip_spatial_index: Res<TripSpatialIndex>,
    settings: Res<ProjectSettings>,
    trip_meta_q: Query<(&Name, &TripClass), With<Trip>>,
    stroke_q: Query<&DisplayedStroke, With<Class>>,
    timer: Res<GlobalTimer>,
    mut selected_items: ResMut<SelectedItems>,
) -> Option<Option<SelectedItem>> {
    buffer.clear();

    let state: GraphState<'_> = selected_items.as_mut().into();

    let selection_strength = painter.ctx().animate_bool_responsive(
        Id::new("graph selection animation"),
        !matches!(state, GraphState::Idle),
    );

    // prepare time
    let time = timer.read_seconds();
    let repeat_time = settings.repeat_frequency.0 as f64;
    let query_time = if repeat_time > 0.0 {
        time.rem_euclid(repeat_time)
    } else {
        time
    };

    let draw_name = |name: Option<&str>, pos: Pos2, color: Color32| {
        if text_strength > 0.05
            && let Some(name) = name
        {
            painter.text(
                pos + Vec2 { x: 7.0, y: 0.0 },
                Align2::LEFT_CENTER,
                name,
                FontId::proportional(13.0),
                color.gamma_multiply(text_strength),
            );
        }
    };

    // in the case of pushing a selected item the interface only allows pushing if:
    // there is interaction i.e. maybe_interaction_pos is Some AND there aren't any
    // previously selected items AND one of the following:
    //   1. the current state is idle, OR
    //   2. the current state's items matches the pushed item's type. e.g. SelectingStations and
    //      StationSelection
    let mut selected_item: Option<SelectedItem> = None;
    macro_rules! push_selected_item {
        ($f:expr, $p:pat) => {
            if let Some(interact_pos) = maybe_interact_pos
                && selected_item.is_none()
                && matches!(state, GraphState::Idle | $p)
                && let Some(candidate_item) = $f(interact_pos)
            {
                selected_item = Some(candidate_item);
            }
        };
    }

    // prepare visuals
    let color = PredefinedColor::Neutral.get(is_dark);
    let margin_x = 12.0 / navi.zoom_x().max(f32::EPSILON) as f64;
    let margin_y = 12.0 / navi.zoom_y().max(f32::EPSILON) as f64;
    let visible_x = navi.visible_x();
    let visible_y = navi.visible_y();
    let min_x = visible_x.start - margin_x;
    let max_x = visible_x.end + margin_x;
    let min_y = visible_y.start - margin_y;
    let max_y = visible_y.end + margin_y;

    const STATION_SELECTION_RADIUS: f32 = 10.0;
    const SELECTION_RADIUS: f32 = 10.0;

    // intervals
    // TODO: interval selection
    for segment in interval_spatial_index.query_xy_aabb(min_x, min_y, max_x, max_y) {
        let spos = navi.xy_to_screen_pos(segment.p0[0], segment.p0[1]);
        let tpos = navi.xy_to_screen_pos(segment.p1[0], segment.p1[1]);
        buffer.push(gpu_draw::ShapeInstance::segment(spos, tpos, 1.0, color));
    }

    // prepare candidates
    let candidate_nodes: Vec<Entity> =
        spatial_index.entities_in_xy_aabb(min_x, min_y, max_x, max_y);

    // draw station selection
    let selected = match state {
        GraphState::SelectingStations(it) => it,
        GraphState::SelectingStation(it) => std::slice::from_ref(it),
        _ => &[],
    };
    for (_, node, _) in nodes.iter_many(selected.into_iter().map(|it| it.station)) {
        let [x, y] = node.coor.to_xy_arr();
        let pos = navi.xy_to_screen_pos(x, y);
        painter.circle(
            pos,
            SELECTION_RADIUS,
            Color32::RED
                .gamma_multiply(0.5)
                .gamma_multiply(selection_strength),
            Stroke::new(1.0, Color32::RED.gamma_multiply(selection_strength)),
        );
    }

    // draw other stations
    for (station_entity, node, name) in nodes.iter_many(candidate_nodes) {
        let [x, y] = node.coor.to_xy_arr();
        let station_screen_pos = navi.xy_to_screen_pos(x, y);
        push_selected_item!(
            |pos| {
                let r = Rect::from_pos(station_screen_pos).expand(STATION_SELECTION_RADIUS);
                r.contains(pos)
                    .then_some(SelectedItem::Station(StationSelection {
                        station: station_entity,
                    }))
            },
            GraphState::SelectingStations(_) | GraphState::SelectingStation(_)
        );

        buffer.push(gpu_draw::ShapeInstance::circle(
            station_screen_pos,
            4.0,
            color,
        ));
        draw_name(name.map(Name::as_str), station_screen_pos, color);
    }

    // entries
    for sample in
        trip_spatial_index.query_xy_time(min_x..=max_x, min_y..=max_y, query_time..=query_time)
    {
        let (name, trip_class) = trip_meta_q
            .get(sample.trip)
            .expect("Trips should have a name and a class");
        let stroke = stroke_q
            .get(trip_class.entity())
            .expect("Classes should have a stroke");
        let color = stroke.color.get(is_dark);

        let pos0 = navi.xy_to_screen_pos(sample.p0[0], sample.p0[1]);
        let pos1 = navi.xy_to_screen_pos(sample.p1[0], sample.p1[1]);
        let entry_pos = if query_time <= sample.t1 {
            pos0
        } else if query_time >= sample.t2 {
            pos1
        } else {
            let f = (query_time - sample.t1) / (sample.t2 - sample.t1).max(f64::EPSILON);
            pos0.lerp(pos1, f as f32)
        };

        push_selected_item!(
            |pos| {
                let r = Rect::from_pos(entry_pos).expand(STATION_SELECTION_RADIUS);
                r.contains(pos).then_some(SelectedItem::Trip(TripSelection {
                    entries: vec1::vec1![sample.entry1],
                    trip: sample.trip,
                }))
            },
            GraphState::SelectingTrips(_)
        );

        if let GraphState::SelectingTrips(trips) = state
            && trips.iter().any(|it| it.trip == sample.trip)
        {
            painter.circle(
                entry_pos,
                SELECTION_RADIUS,
                Color32::BLUE
                    .gamma_multiply(0.5)
                    .gamma_multiply(selection_strength),
                Stroke::new(1.0, Color32::BLUE.gamma_multiply(selection_strength)),
            );
        }

        buffer.push(gpu_draw::ShapeInstance::stealth_arrow(
            pos0, pos1, entry_pos, color,
        ));
        draw_name(Some(name.as_str()), entry_pos, color);
    }

    maybe_interact_pos.map(|_| selected_item)
}

use bevy::ecs::entity::EntityHashMap;
use bevy::prelude::*;
use paiagram_core::entry::{EntryEstimate, EntryQuery};
use paiagram_core::route::{Route, RouteTrips};
use paiagram_core::station::ParentStationOrStation;
use paiagram_core::trip::TripQuery;
use smallvec::SmallVec;
use vec1::{Vec1, vec1};

use super::{TripCache, TripPoint};

pub(crate) fn calc(
    (In(route_entity), InRef(heights), InMut(map)): (
        In<Entity>,
        InRef<[(Entity, f32)]>,
        InMut<Option<TripCache>>,
    ),
    route_q: Query<(&RouteTrips, Ref<Route>)>,
    trip_q: Query<TripQuery>,
    changed_entries: Query<&ChildOf, Changed<EntryEstimate>>,
    entries: Query<EntryQuery>,
    parent_station_or_station: Query<ParentStationOrStation>,
    mut invalidate_cache: Local<Vec<Entity>>,
) -> bool {
    let (trips, route) = route_q.get(route_entity).unwrap();

    let refresh_candidates = if map.is_none() || route.is_changed() {
        trips.as_slice()
    } else {
        if changed_entries.is_empty() {
            return false;
        }
        let mut trips = trips.to_vec();
        trips.sort_unstable();
        invalidate_cache.clear();
        for entity in changed_entries.iter().map(ChildOf::parent) {
            let Ok(_) = trips.binary_search(&entity) else {
                continue;
            };
            invalidate_cache.push(entity);
        }
        invalidate_cache.sort_unstable();
        invalidate_cache.dedup();
        invalidate_cache.as_slice()
    };

    let map: &mut EntityHashMap<SmallVec<[Vec1<TripPoint>; 1]>> = map.get_or_insert_default();

    #[derive(Clone, Copy)]
    struct TripEntryData {
        entity: Entity,
        station: Entity,
        estimate: Option<EntryEstimate>,
    }

    struct TripData {
        entity: Entity,
        // stroke: DisplayedStroke,
        entries: Vec<TripEntryData>,
    }

    let stations_for_layout = &heights[..];
    let mut station_index_map: EntityHashMap<SmallVec<[usize; 2]>> = EntityHashMap::new();
    for (idx, (station, _)) in stations_for_layout.iter().enumerate() {
        station_index_map.entry(*station).or_default().push(idx);
    }

    let mut trip_data = Vec::with_capacity(refresh_candidates.len());
    for trip_entity in refresh_candidates.iter().copied() {
        let trip = trip_q.get(trip_entity).unwrap();
        let mut trip_entries_vec: Vec<TripEntryData> = Vec::new();
        for entry_entity in trip.schedule.iter().copied() {
            let entry = entries.get(entry_entity).unwrap();
            let station_entity = parent_station_or_station
                .get(entry.stop())
                .unwrap()
                .parent();
            trip_entries_vec.push(TripEntryData {
                entity: entry_entity,
                station: station_entity,
                estimate: entry.estimate.copied(),
            });
        }

        if trip_entries_vec.len() < 2 {
            continue;
        }

        trip_data.push(TripData {
            entity: trip_entity,
            entries: trip_entries_vec,
        });
    }

    for trip in trip_data.into_iter() {
        let trip_bucket = map.entry(trip.entity).or_default();
        trip_bucket.clear();

        let mut push_to_bucket = |points: Vec1<TripPoint>| {
            if points.len() < 2 {
                return;
            }
            trip_bucket.push(points);
        };

        let trip_entries = trip.entries.as_slice();
        if trip_entries.len() < 2 {
            continue;
        }

        // points, end index
        let mut local_edges: Vec<Vec1<TripPoint>> = Vec::new();
        let mut previous_indices: &[usize] = &[];

        if let Some(first) = trip_entries.first()
            && let Some(indices) = station_index_map.get(&first.station)
        {
            previous_indices = indices.as_slice();
        }

        for entry_idx in 0..trip_entries.len() {
            let curr = &trip_entries[entry_idx];
            let next = trip_entries.get(entry_idx + 1);

            if previous_indices.is_empty() {
                if let Some(next) = next {
                    if let Some(indices) = station_index_map.get(&next.station) {
                        previous_indices = indices.as_slice();
                    } else {
                        previous_indices = &[];
                    }
                }
                for it in local_edges.drain(..) {
                    push_to_bucket(it)
                }
                continue;
            }

            let Some(estimate) = curr.estimate else {
                for it in local_edges.drain(..) {
                    push_to_bucket(it)
                }
                if let Some(next_entry) = next {
                    if let Some(indices) = station_index_map.get(&next_entry.station) {
                        previous_indices = indices.as_slice();
                    } else {
                        previous_indices = &[];
                    }
                }
                continue;
            };

            let mut next_local_edges: Vec<Vec1<TripPoint>> = Vec::new();

            for current_line_index in previous_indices.iter().copied() {
                let matched_idx = local_edges
                    .iter()
                    .position(|it| current_line_index.abs_diff(it.last().station_index) <= 1);

                let segment = if let Some(idx) = matched_idx {
                    let mut a = local_edges.swap_remove(idx);
                    a.push(TripPoint {
                        arr: estimate.arr,
                        dep: estimate.dep,
                        entry: curr.entity,
                        station_index: current_line_index,
                    });
                    a
                } else {
                    vec1![TripPoint {
                        arr: estimate.arr,
                        dep: estimate.dep,
                        entry: curr.entity,
                        station_index: current_line_index,
                    }]
                };

                let mut segment = Some(segment);
                if let Some(next_entry) = next {
                    for offset in [-1, 0, 1] {
                        let next_idx = (current_line_index as isize + offset) as usize;
                        if let Some((s, _)) = stations_for_layout.get(next_idx) {
                            if *s == next_entry.station {
                                let forwarded_segment = segment.take().unwrap();
                                next_local_edges.push(forwarded_segment);
                                break;
                            }
                        }
                    }
                }

                if let Some(it) = segment {
                    push_to_bucket(it);
                }
            }

            for it in local_edges.drain(..) {
                push_to_bucket(it)
            }

            local_edges = next_local_edges;
            if let Some(next_entry) = next {
                if let Some(indices) = station_index_map.get(&next_entry.station) {
                    previous_indices = indices.as_slice();
                } else {
                    previous_indices = &[];
                }
            }
        }

        for it in local_edges.drain(..) {
            push_to_bucket(it)
        }
    }
    return true;
}

use bevy::prelude::*;
use egui::{Color32, FontId, Painter, Pos2, Stroke, Visuals};
use paiagram_core::units::time::{Tick, TimetableTime};

use crate::tabs::Navigatable;
use crate::tabs::diagram::DiagramTabNavigation;

pub(crate) fn draw_station_lines(
    painter: &mut Painter,
    navi: &DiagramTabNavigation,
    to_draw: impl Iterator<Item = (Entity, f32)>,
    visuals: &Visuals,
    world: &World,
) {
    // TODO: implement per-station stroke
    let stroke = Stroke {
        width: 0.6,
        color: visuals.window_stroke().color,
    };
    for (station_entity, raw_height) in to_draw {
        let mut height = navi.logical_y_to_screen_y(raw_height as f64);
        stroke.round_center_to_pixel(painter.pixels_per_point(), &mut height);
        painter.hline(
            navi.visible_rect.left()..=navi.visible_rect.right(),
            height,
            stroke,
        );
        let layout = painter.layout_no_wrap(
            world
                .get::<Name>(station_entity)
                .map_or("<Unknown>".to_string(), Name::to_string),
            egui::FontId::proportional(13.0),
            visuals.text_color(),
        );
        let layout_pos = Pos2 {
            x: navi.visible_rect.left(),
            y: height - layout.size().y,
        };
        painter.galley(layout_pos, layout, visuals.text_color());
    }
}

/// Draw vertical time lines and labels
pub(crate) fn draw_time_lines(painter: &mut Painter, navi: &DiagramTabNavigation) {
    const MAX_SCREEN_WIDTH: f64 = 64.0;
    const MIN_SCREEN_WIDTH: f64 = 32.0;
    let sizes = [
        Tick::from_timetable_time(TimetableTime(1)).0, // 1 second
        Tick::from_timetable_time(TimetableTime(10)).0, // 10 seconds
        Tick::from_timetable_time(TimetableTime(30)).0, // 30 seconds
        Tick::from_timetable_time(TimetableTime(60)).0, // 1 minute
        Tick::from_timetable_time(TimetableTime(60 * 5)).0, // 5 minutes
        Tick::from_timetable_time(TimetableTime(60 * 10)).0, // 10 minutes
        Tick::from_timetable_time(TimetableTime(60 * 30)).0, // 30 minutes
        Tick::from_timetable_time(TimetableTime(60 * 60)).0, // 1 hour
        Tick::from_timetable_time(TimetableTime(60 * 60 * 4)).0, // 4 hours
        Tick::from_timetable_time(TimetableTime(60 * 60 * 24)).0, // 1 day
    ];
    let visible_ticks = navi.visible_x();
    let ticks_per_screen_unit = navi.x_per_screen_unit_f64();
    let screen_rect = navi.visible_rect();
    let pixels_per_point = painter.pixels_per_point();
    let mut drawn: Vec<i64> = Vec::with_capacity(30);

    // align the first tick to a spacing boundary that is <= visible start.
    let first_visible_position = sizes
        .iter()
        .position(|s| *s as f64 / ticks_per_screen_unit * 1.5 > MIN_SCREEN_WIDTH)
        .unwrap_or(0);
    let visible = &sizes[first_visible_position..];
    for (i, spacing) in visible.iter().enumerate().rev() {
        let first = visible_ticks.start.0 - visible_ticks.start.0.rem_euclid(*spacing) - spacing;
        let mut tick = first;
        let strength = (((*spacing as f64 / ticks_per_screen_unit * 1.5) - MIN_SCREEN_WIDTH)
            / (MAX_SCREEN_WIDTH - MIN_SCREEN_WIDTH))
            .clamp(0.0, 1.0);
        if strength < 0.1 {
            continue;
        }
        // TODO: make stroke depend on current theme
        let mut current_stroke = Stroke {
            width: 0.6,
            color: Color32::GRAY,
        };
        if strength.is_finite() {
            // strange bug here
            current_stroke.color = current_stroke.color.gamma_multiply(strength as f32);
        }
        current_stroke.width = 0.5;
        while tick <= visible_ticks.end.0 {
            tick += *spacing;
            if drawn.contains(&tick) {
                continue;
            }
            let mut x = navi.logical_x_to_screen_x(Tick(tick));
            current_stroke.round_center_to_pixel(pixels_per_point, &mut x);
            painter.vline(x, screen_rect.top()..=screen_rect.bottom(), current_stroke);
            drawn.push(tick);
            let time = Tick(tick).to_timetable_time();
            let mut offset = screen_rect.top();
            let text = match i + first_visible_position {
                0..=2 => time.to_hmsd().2.to_string(),
                3..=8 => format!("{}:{:02}", time.to_hmsd().0, time.to_hmsd().1),
                9 => {
                    offset += 13.0;
                    time.to_string()
                }
                _ => unreachable!(),
            };
            let label = painter.layout_no_wrap(
                text,
                FontId::new(13.0, egui::FontFamily::Proportional),
                current_stroke.color,
            );
            painter.galley(
                Pos2 {
                    x: x - label.size().x / 2.0,
                    y: offset,
                },
                label,
                current_stroke.color,
            );
        }
    }
}

use bevy::prelude::*;
use eros::bail;
use paiagram_core::entry::{AdjustEntryMode, EntryMode, EntryModeAdjustment, transform_entry_mode};

use super::RevertableActions::ChangeEntryMode as ChangeEntryModeWrapper;

pub(super) fn watch_entry_mode_changes(
    msg: On<AdjustEntryMode>,
    entry_q: Query<&EntryMode>,
    time: Res<Time>,
    mut action_history: ResMut<super::ActionHistory>,
) {
    /// permissive threshold for such interactions
    const MERGE_THRESHOLD_MS: std::time::Duration = std::time::Duration::from_millis(1000);
    let previous_state = entry_q.get(msg.entity).unwrap();
    let new_state = transform_entry_mode(*previous_state, msg.adj);
    let action_inner = ChangeEntryModeInner {
        entry: msg.entity,
        previous_state: *previous_state,
        new_state,
    };
    let action = match msg.adj {
        EntryModeAdjustment::ShiftArrival(_) => {
            ChangeEntryMode::ShiftArrival((action_inner, time.elapsed()))
        }
        EntryModeAdjustment::ShiftDeparture(_) => {
            ChangeEntryMode::ShiftDeparture((action_inner, time.elapsed()))
        }
        _ => ChangeEntryMode::Other(action_inner),
    };
    match (action, action_history.history.back_mut()) {
        (
            ChangeEntryMode::ShiftArrival((a1, t1)),
            Some(ChangeEntryModeWrapper(ChangeEntryMode::ShiftArrival((a2, t2)))),
        )
        | (
            ChangeEntryMode::ShiftDeparture((a1, t1)),
            Some(ChangeEntryModeWrapper(ChangeEntryMode::ShiftDeparture((a2, t2)))),
        ) if (t1 - *t2) < MERGE_THRESHOLD_MS => {
            a2.new_state = a1.new_state;
            *t2 = t1;
        }
        (action, _) => {
            action_history.add(ChangeEntryModeWrapper(action));
        }
    }
}

#[derive(Reflect)]
pub(super) enum ChangeEntryMode {
    ShiftArrival((ChangeEntryModeInner, std::time::Duration)),
    ShiftDeparture((ChangeEntryModeInner, std::time::Duration)),
    Other(ChangeEntryModeInner),
}

impl super::RevertableAction for ChangeEntryMode {
    fn undo(&self, world: &mut World) -> eros::Result<()> {
        match self {
            Self::ShiftArrival((t, _)) => t.undo(world),
            Self::ShiftDeparture((t, _)) => t.undo(world),
            Self::Other(t) => t.undo(world),
        }
    }
    fn redo(&self, world: &mut World) -> eros::Result<()> {
        match self {
            Self::ShiftArrival((t, _)) => t.redo(world),
            Self::ShiftDeparture((t, _)) => t.redo(world),
            Self::Other(t) => t.redo(world),
        }
    }
}

#[derive(Reflect)]
pub(super) struct ChangeEntryModeInner {
    entry: Entity,
    previous_state: EntryMode,
    new_state: EntryMode,
}

impl super::RevertableAction for ChangeEntryModeInner {
    fn undo(&self, world: &mut World) -> eros::Result<()> {
        let Some(mut mode) = world.get_mut::<EntryMode>(self.entry) else {
            bail!("The entry has been modified or deleted")
        };
        *mode = self.previous_state;
        Ok(())
    }
    fn redo(&self, world: &mut World) -> eros::Result<()> {
        let Some(mut mode) = world.get_mut::<EntryMode>(self.entry) else {
            bail!("The entry has been modified or deleted")
        };
        *mode = self.new_state;
        Ok(())
    }
}

use bevy::prelude::*;
use egui::{RectAlign, Response, Ui, Vec2, vec2};
use paiagram_core::entry::{
    AdjustEntryMode, EntryEstimate, EntryMode, EntryModeAdjustment, EntryQueryItem, TravelMode,
};
use paiagram_core::trip::TripQueryItem;
use paiagram_core::units::time::{Duration, TimetableTime};

use super::{DurationDragValue, TimeDragValue};

pub(crate) const POPUP_WIDTH: f32 = 130.0;
pub(crate) const BUTTON_SIZE: Vec2 = vec2(70.0, 18.0);

pub(crate) fn departure_popup(
    response: &Response,
    entry: &EntryQueryItem,
    alignment: RectAlign,
    commands: &mut Commands,
) {
    egui::Popup::menu(&response)
        .align(alignment)
        .close_behavior(egui::PopupCloseBehavior::CloseOnClickOutside)
        .show(|ui| departure_popup_inner(ui, entry, commands));
}

pub(crate) fn shift_at_value(
    t: TimetableTime,
    trip_entity: Entity,
    ui: &mut Ui,
    commands: &mut Commands,
    button_size: Vec2,
    is_arrival: bool,
) -> Response {
    let mut new_t = t;
    let res = ui.add_sized(button_size, TimeDragValue(&mut new_t));
    if res.changed() {
        commands.trigger(AdjustEntryMode {
            entity: trip_entity,
            adj: if is_arrival {
                EntryModeAdjustment::ShiftArrival(new_t - t)
            } else {
                EntryModeAdjustment::ShiftDeparture(new_t - t)
            },
        });
    }
    res
}

pub(crate) fn shift_for_value(
    d: Duration,
    trip_entity: Entity,
    ui: &mut Ui,
    commands: &mut Commands,
    button_size: Vec2,
    is_arrival: bool,
) -> Response {
    let mut new_d = d;
    let res = ui.add_sized(button_size, DurationDragValue(&mut new_d));
    if res.changed() {
        commands.trigger(AdjustEntryMode {
            entity: trip_entity,
            adj: if is_arrival {
                EntryModeAdjustment::ShiftArrival(new_d - d)
            } else {
                EntryModeAdjustment::ShiftDeparture(new_d - d)
            },
        });
    }
    res
}

pub(crate) fn departure_popup_inner(ui: &mut Ui, entry: &EntryQueryItem, commands: &mut Commands) {
    ui.set_width(POPUP_WIDTH);
    // at
    let mut adjustment = None;
    let at_time = entry.estimate.map(|e| e.dep).unwrap_or_default();
    let enable_at = !matches!(entry.mode.dep, TravelMode::At(_));
    if enable_at {
        if ui
            .add(egui::Button::new("At").right_text(at_time.to_string()))
            .clicked()
        {
            adjustment = Some(EntryModeAdjustment::SetDeparture(TravelMode::At(at_time)));
        };
    } else {
        shift_at_value(at_time, entry.entity, ui, commands, BUTTON_SIZE, false);
    }
    // for
    let for_dur = if let TravelMode::For(d) = entry.mode.dep {
        Some(d)
    } else if let Some(e) = entry.estimate {
        Some(e.dep - e.arr)
    } else {
        None
    }
    .unwrap_or_default();
    let enable_for = !matches!(entry.mode.dep, TravelMode::For(_));
    if enable_for {
        if ui
            .add(egui::Button::new("For").right_text(for_dur.to_string()))
            .clicked()
        {
            adjustment = Some(EntryModeAdjustment::SetDeparture(TravelMode::For(for_dur)));
            ui.close();
        }
    } else {
        shift_for_value(for_dur, entry.entity, ui, commands, BUTTON_SIZE, false);
    }
    // flexible
    if ui
        .add_enabled(
            !matches!(entry.mode.dep, TravelMode::Flexible),
            egui::Button::new("Flexible").right_text("〇"),
        )
        .clicked()
    {
        adjustment = Some(EntryModeAdjustment::SetDeparture(TravelMode::Flexible));
    }
    if let Some(adj) = adjustment {
        commands.trigger(AdjustEntryMode {
            entity: entry.entity,
            adj,
        });
    }
}

pub(crate) fn arrival_popup(
    response: &Response,
    entry: &EntryQueryItem,
    parent: &TripQueryItem,
    entry_q: &Query<(&EntryMode, Option<&EntryEstimate>)>,
    alignment: RectAlign,
    commands: &mut Commands,
) {
    egui::Popup::menu(&response)
        .align(alignment)
        .close_behavior(egui::PopupCloseBehavior::CloseOnClickOutside)
        .show(|ui| arrival_popup_inner(ui, entry, parent, entry_q, commands));
}

pub(crate) fn arrival_popup_inner(
    ui: &mut Ui,
    entry: &EntryQueryItem,
    parent: &TripQueryItem,
    entry_q: &Query<(&EntryMode, Option<&EntryEstimate>)>,
    commands: &mut Commands,
) {
    ui.set_width(POPUP_WIDTH);
    // at
    let at_time = entry.estimate.map(|e| e.arr).unwrap_or_default();
    let mut adjustment = None;
    let enable_at = !matches!(entry.mode.arr, Some(TravelMode::At(_)));
    if enable_at {
        if ui
            .add(egui::Button::new("At").right_text(at_time.to_string()))
            .clicked()
        {
            adjustment = Some(EntryModeAdjustment::SetArrival(Some(TravelMode::At(
                at_time,
            ))));
        };
    } else {
        shift_at_value(at_time, entry.entity, ui, commands, BUTTON_SIZE, true);
    }
    // for
    let for_dur = if let Some(TravelMode::For(d)) = entry.mode.arr {
        Some(d)
    } else {
        entry.travel_duration(parent, entry_q)
    }
    .unwrap_or_default();
    let enable_for = !matches!(entry.mode.arr, Some(TravelMode::For(_)));
    if enable_for {
        if ui
            .add(egui::Button::new("For").right_text(for_dur.to_string()))
            .clicked()
        {
            adjustment = Some(EntryModeAdjustment::SetArrival(Some(TravelMode::For(
                for_dur,
            ))));
        };
    } else {
        shift_for_value(for_dur, entry.entity, ui, commands, BUTTON_SIZE, true);
    }
    // flexible
    if ui
        .add_enabled(
            !matches!(entry.mode.arr, Some(TravelMode::Flexible)),
            egui::Button::new("Flexible").right_text("〇"),
        )
        .clicked()
    {
        adjustment = Some(EntryModeAdjustment::SetArrival(Some(TravelMode::Flexible)));
    }
    // non-stop
    if ui
        .add_enabled(
            !matches!(entry.mode.arr, None),
            egui::Button::new("Non-stop").right_text("↓"),
        )
        .clicked()
    {
        adjustment = Some(EntryModeAdjustment::SetArrival(None));
    }
    if let Some(adj) = adjustment {
        commands.trigger(AdjustEntryMode {
            entity: entry.entity,
            adj,
        });
    }
}

