use bevy::math::ops::sqrt;
use egui::{Color32, Painter, Pos2, Shape, Stroke};

pub(crate) fn circle_button_shape(
    painter: &mut Painter,
    center: Pos2,
    diameter: f32,
    stroke: Stroke,
    fill_color: Color32,
) {
    painter.circle(center, diameter / 2.0, fill_color, stroke);
}

pub(crate) fn triangle_button_shape(
    painter: &mut Painter,
    center: Pos2,
    base: f32,
    stroke: Stroke,
    fill_color: Color32,
) {
    let dx = base / 4.0 * sqrt(3.0);
    let a = Pos2 {
        x: center.x - dx,
        y: center.y - base / 2.0,
    };
    let b = Pos2 {
        x: center.x + dx,
        y: center.y,
    };
    let c = Pos2 {
        x: a.x,
        y: center.y + base / 2.0,
    };
    painter.add(Shape::convex_polygon(vec![a, b, c], fill_color, stroke));
}

pub(crate) fn double_triangle(
    painter: &mut Painter,
    center: Pos2,
    base: f32,
    stroke: Stroke,
    fill_color: Color32,
) {
    triangle_button_shape(painter, center, base, stroke, fill_color);
    triangle_button_shape(
        painter,
        Pos2 {
            x: center.x + 5.0,
            y: center.y,
        },
        base,
        stroke,
        fill_color,
    );
}

pub(crate) fn dash_button_shape(
    painter: &mut Painter,
    center: Pos2,
    base: f32,
    stroke: Stroke,
    fill_color: Color32,
) {
    let a = Pos2 {
        x: center.x - base / 2.0 - base / 2.0 / sqrt(3.0),
        y: center.y - base / 2.0,
    };
    let b = Pos2 {
        x: a.x + base,
        y: a.y,
    };
    let c = Pos2 {
        x: center.x + base / 2.0,
        y: center.y,
    };
    let d = Pos2 {
        x: b.x,
        y: center.y + base / 2.0,
    };
    let e = Pos2 { x: a.x, y: d.y };
    let f = Pos2 {
        x: center.x - base / 2.0,
        y: center.y,
    };
    painter.add(Shape::convex_polygon(
        vec![a, b, c, f],
        fill_color,
        Stroke::NONE,
    ));
    painter.add(Shape::convex_polygon(
        vec![f, c, d, e],
        fill_color,
        Stroke::NONE,
    ));
    painter.line_segment(
        [c, f],
        Stroke {
            width: 2.0,
            color: fill_color,
        },
    );
    painter.add(Shape::closed_line(vec![a, b, c, d, e, f], stroke));
}

use egui::{Color32, Id, Painter, Rect, Shadow};

/// Display the time indicator's indicator given the SCREEN coordinates
/// of the clip rect and the time indicator.
pub(crate) fn display_time_indicator_indicator_vertical(
    id: Id,
    rect: Rect,
    time_indicator_y: f32,
    color: Color32,
    painter: &Painter,
) {
    let y_range = rect.y_range();
    let in_viewport = y_range.contains(time_indicator_y);
    let view_strength = painter.ctx().animate_bool(id, !in_viewport);
    let rect = if time_indicator_y < (y_range.min + y_range.max) / 2.0 {
        Rect::from_two_pos(rect.left_top(), rect.right_top())
    } else {
        Rect::from_two_pos(rect.left_bottom(), rect.right_bottom())
    };
    let shape = Shadow {
        offset: [0, 0],
        blur: 255,
        spread: (8.0 * view_strength) as u8,
        color: color.gamma_multiply(0.2).gamma_multiply(view_strength),
    }
    .as_shape(rect, 0);
    painter.add(shape);
}

/// Display the time indicator's indicator given the SCREEN coordinates
/// of the clip rect and the time indicator.
pub(crate) fn display_time_indicator_indicator_horizontal(
    id: Id,
    rect: Rect,
    time_indicator_x: f32,
    color: Color32,
    painter: &Painter,
) {
    let x_range = rect.x_range();
    let in_viewport = x_range.contains(time_indicator_x);
    let view_strength = painter.ctx().animate_bool(id, !in_viewport);
    let rect = if time_indicator_x < (x_range.min + x_range.max) / 2.0 {
        Rect::from_two_pos(rect.left_top(), rect.left_bottom())
    } else {
        Rect::from_two_pos(rect.right_top(), rect.right_bottom())
    };
    let shape = Shadow {
        offset: [0, 0],
        blur: 255,
        spread: (8.0 * view_strength) as u8,
        color: color.gamma_multiply(0.2).gamma_multiply(view_strength),
    }
    .as_shape(rect, 0);
    painter.add(shape);
}

