fn make_classes(
    world: &WorldSnapshot,
    buf: &mut Vec<Structure<'static>>,
) -> std::collections::HashMap<usize, usize> {
    let mut class_map = std::collections::HashMap::new();
    for (i, ck) in world.classes.keys().enumerate() {
        class_map.insert(i, i);
        let view = world.classes.get_view(*ck);
        if let Some(view) = view {
            let color = view.style.color.get(true);
            let color_string = format!(
                "00{:02X}{:02X}{:02X}",
                color.b(),
                color.g(),
