impl SelectedItems {
    fn toggle_entries<T: Ord + Clone>(entries: &mut Vec1<T>, incoming: impl Iterator<Item = T>) -> bool {
        entries.extend(incoming);
        entries.sort_unstable();
        let mut result = Vec::new();
        let mut i = 0;
        let data = entries.as_vec();
        while i < data.len() {
            let mut j = i + 1;
            while j < data.len() && data[j] == data[i] { j += 1; }
            if (j - i) % 2 != 0 { result.push(data[i].clone()); }
            i = j;
        }
        if result.is_empty() { true }
        else { *entries = Vec1::try_from_vec(result).unwrap(); false }
    }
    pub(crate) fn toggle_selection(&mut self, item: SelectedItem) {
        let mut should_reset = false;
        match (item, &mut *self) {
            (SelectedItem::None, _) => return,
            (SelectedItem::Trip(sel), Self::Trips(it)) => {
                it.sort_unstable_by_key(|t| t.trip);
                match it.binary_search_by_key(&sel.trip, |t| t.trip) {
                    Ok(idx) => {
                        if Self::toggle_entries(&mut it[idx].entries, sel.entries.into_iter()) {
                            if it.len() == 1 { should_reset = true; }
                            else { it.remove(idx); }
                        }
                    }
                    Err(idx) => { it.insert(idx, sel); }
                }
            }
            (SelectedItem::Interval(sel), Self::Intervals(it)) => {
                should_reset = Self::toggle_entries(it, std::iter::once(sel));
            }
            (SelectedItem::Station(sel), Self::Stations(it)) => {
                should_reset = Self::toggle_entries(it, std::iter::once(sel));
            }
            _ => {}
        }
        if should_reset { *self = SelectedItems::None; }
    }
    pub(crate) fn set_single_selection(&mut self, item: SelectedItem) {
        match item {
            SelectedItem::None => *self = Self::None,
            SelectedItem::Trip(it) => *self = Self::Trips(vec1::vec1![it]),
            SelectedItem::Interval(it) => *self = Self::Intervals(vec1::vec1![it]),
            SelectedItem::Station(it) => *self = Self::Stations(vec1::vec1![it]),
            SelectedItem::Coordinate(coor) => *self = Self::Coordinate(coor),
        }
    }
}

