#[derive(Serialize, Deserialize, Clone)]
pub(crate) struct MainUiState {
    pub tree: Tree<MainTab>,
    pub maximized: Option<TileId>,
}

impl MainUiState {
    pub(crate) fn push_to_focused_leaf(&mut self, new_pane: MainTab) -> TileId {
        let new_id = self.tree.tiles.insert_pane(new_pane);
        if let Some(&active_id) = self.tree.active_tiles().last()
            && let Some(parent_id) = self.tree.tiles.parent_of(active_id)
            && let Some(Tile::Container(container)) = self.tree.tiles.get_mut(parent_id)
            && container.kind() == ContainerKind::Tabs
        {
            container.add_child(new_id);
            self.tree.make_active(|id, _| id == new_id);
            return new_id;
        }
        let old_root = self.tree.root;
        let tabs_id = if let Some(old_root) = old_root {
            self.tree.tiles.insert_tab_tile(vec![old_root, new_id])
        } else {
            self.tree.tiles.insert_tab_tile(vec![new_id])
        };
        self.tree.root = Some(tabs_id);
        self.tree.make_active(|id, _| id == new_id);
        new_id
    }
}

impl Default for MainUiState {
    fn default() -> Self {
        Self {
            tree: Tree::new_tabs("main", vec![MainTab::Start(StartTab::default())]),
            maximized: None,
        }
    }
}

pub(crate) fn open_or_focus_tab(mus: &mut MainUiState, tab: MainTab) {
    if let Some(tile_id) = mus.tree.tiles.find_pane(&tab) {
        mus.make_active(|id, _| id == tile_id);
        mus.set_visible(tile_id, true);
    } else {
        mus.push_to_focused_leaf(tab);
    }
}

impl MainUiState {
    pub fn set_visible(&mut self, tile_id: TileId, visible: bool) {
        if let Some(Tile::Container(container)) = self.tree.tiles.get_mut(tile_id) {
            container.set_visible(visible);
        }
    }
    pub fn make_active(&mut self, f: impl Fn(TileId) -> bool) {
        self.tree.make_active(f);
    }
    pub fn find_pane(&self, tab: &MainTab) -> Option<TileId> {
        self.tree.tiles.find_pane(tab)
    }
}

struct MainTabViewer<'a> {
    app: &'a mut tabs::AppState,
    last_focused_id: &'a mut Option<TileId>,
    last_maximized_id: &'a mut Option<TileId>,
}

impl<'a> MainTabViewer<'a> {
    fn add_popup(&mut self, ui: &mut Ui) {
        let tab_definitions: [(&str, _); 4] = [
            (&tr!("tab-start"), MainTab::Start(StartTab::default())),
            (&tr!("tab-settings"), MainTab::Settings(SettingsTab)),
            (&tr!("tab-classes"), MainTab::Classes(ClassesTab::default())),
            (&tr!("tab-graph"), MainTab::Graph(GraphTab::default())),
        ];
        for (s, t) in tab_definitions {
            if ui.button(s).clicked() { open_or_focus_tab(&mut self.app.main_ui, t); ui.close(); }
        }
        ui.menu_button(tr!("menu-route-timetable"), |ui| {
            if ui.button(tr!("menu-new-route")).clicked() {}
            ui.separator();
            ScrollArea::vertical().show(ui, |ui| {
                for (rk, name) in self.app.source.routes_iter() {
                    if ui.button(name.as_str()).clicked() {
                        open_or_focus_tab(&mut self.app.main_ui, MainTab::RouteTimetable(RouteTimetableTab::new(rk)));
                    }
                }
            });
        });
        ui.menu_button(tr!("menu-priority-graph"), |ui| {
            if ui.button(tr!("menu-new-route")).clicked() {}
            ui.separator();
            ScrollArea::vertical().show(ui, |ui| {
                for (rk, name) in self.app.source.routes_iter() {
                    if ui.button(name.as_str()).clicked() {
                        open_or_focus_tab(&mut self.app.main_ui, MainTab::PriorityGraph(PriorityGraphTab::new(rk)));
                    }
                }
            });
        });
        ui.menu_button(tr!("menu-diagrams"), |ui| {
            if ui.button(tr!("menu-new-route")).clicked() {}
            ui.separator();
            ScrollArea::vertical().show(ui, |ui| {
                for (rk, name) in self.app.source.routes_iter() {
                    if ui.button(name.as_str()).clicked() {
                        open_or_focus_tab(&mut self.app.main_ui, MainTab::Diagram(DiagramTab::new(rk)));
                    }
                }
            });
        });
        ui.menu_button(tr!("menu-trips"), |ui| {
            if ui.button(tr!("menu-new-trip")).clicked() {}
            ui.separator();
            ScrollArea::vertical().show(ui, |ui| {
                for (tk, name) in self.app.source.trips_iter() {
                    if ui.button(name.as_str()).clicked() {
                        open_or_focus_tab(&mut self.app.main_ui, MainTab::Trip(TripTab::new(tk)));
                    }
                }
            });
        });
        ui.menu_button(tr!("menu-text"), |ui| {
            if ui.button(tr!("menu-new-text-message")).clicked() {
                // TODO: text messages
            }
            ui.separator();
            if ui.button(tr!("menu-project-remarks")).clicked() {
                open_or_focus_tab(&mut self.app.main_ui, MainTab::Text(TextTab::new(None)));
            }
        });
    }
}

impl<'a> Behavior<MainTab> for MainTabViewer<'a> {
    fn tab_title_for_pane(&mut self, pane: &MainTab) -> egui::WidgetText {
        for_all_tabs!(pane, p, p.title())
    }
    fn on_tab_button(&mut self, _tiles: &mut Tiles<MainTab>, tile_id: TileId, button_response: Response) -> Response {
        if button_response.clicked() || button_response.dragged() {
            *self.last_focused_id = Some(tile_id);
        }
        button_response
    }
    fn pane_ui(&mut self, ui: &mut Ui, tile_id: TileId, tab: &mut MainTab) -> UiResponse {
        ui.painter().rect_filled(ui.available_rect_before_wrap(), 0, ui.visuals().panel_fill);
        for_all_tabs!(tab, t, t.main_display(self.app, ui));
        if let Some(pos) = ui.input(|i| i.pointer.press_origin()) && ui.clip_rect().shrink(10.0).contains(pos) {
            *self.last_focused_id = Some(tile_id)
        }
        Default::default()
    }
    fn simplification_options(&self) -> SimplificationOptions {
        SimplificationOptions {
            prune_empty_tabs: true,
            prune_empty_containers: true,
            prune_single_child_tabs: false,
            prune_single_child_containers: true,
            all_panes_must_have_tabs: true,
            join_nested_linear_containers: true,
        }
    }
    fn is_tab_closable(&self, tiles: &Tiles<MainTab>, tile_id: TileId) -> bool {
        match tiles.get(tile_id) {
            None => false,
            Some(Tile::Container(_)) => false,
            Some(Tile::Pane(MainTab::Start(_))) => false,
            Some(Tile::Pane(_)) => true,
        }
    }
    fn top_bar_right_ui(&mut self, _tiles: &Tiles<MainTab>, ui: &mut Ui, _tile_id: TileId, _tabs: &egui_tiles::Tabs, _scroll_offset: &mut f32) {
        if ui.button("M").clicked() { *self.last_maximized_id = *self.last_focused_id; }
        let res = ui.button("+");
        egui::Popup::menu(&res).show(|ui| { self.add_popup(ui); });
    }
    fn tab_bg_color(&self, visuals: &egui::Visuals, tiles: &Tiles<MainTab>, tile_id: TileId, state: &egui_tiles::TabState) -> Color32 {
        let base = match tiles.get(tile_id) {
            None | Some(Tile::Container(_)) => visuals.panel_fill,
            Some(Tile::Pane(tab)) => DisplayedColor::from_seed(for_all_tab_types!(tab, NAME)).get(visuals.dark_mode),
        };
        base.gamma_multiply(if state.active { 0.7 } else { 0.2 })
    }
    fn tab_outline_stroke(&self, visuals: &egui::Visuals, tiles: &Tiles<MainTab>, tile_id: TileId, state: &egui_tiles::TabState) -> Stroke {
        let base = match tiles.get(tile_id) {
            None | Some(Tile::Container(_)) => visuals.panel_fill,
            Some(Tile::Pane(tab)) => DisplayedColor::from_seed(for_all_tab_types!(tab, NAME)).get(visuals.dark_mode),
        };
        Stroke::new(1.0, base.gamma_multiply(if state.active { 1.0 } else { 0.7 }))
    }
    fn tab_bar_hline_stroke(&self, _visuals: &egui::Visuals) -> Stroke { Stroke::new(1.0, Color32::TRANSPARENT) }
}

