struct AdditionalTabViewer<'a> {
    app: &'a mut tabs::AppState,
}

impl<'a> Behavior<AdditionalTab> for AdditionalTabViewer<'a> {
    fn tab_title_for_pane(&mut self, tab: &AdditionalTab) -> egui::WidgetText {
        match *tab {
            AdditionalTab::Edit => tr!("side-panel-edit"),
            AdditionalTab::Properties => tr!("side-panel-details"),
            AdditionalTab::Export => tr!("side-panel-export"),
        }.into()
    }
    fn pane_ui(&mut self, ui: &mut Ui, _tile_id: TileId, tab: &mut AdditionalTab) -> UiResponse {
        ui.painter().rect_filled(ui.available_rect_before_wrap(), 0, ui.visuals().panel_fill);
        egui::Frame::new().inner_margin(6.0).show(ui, |ui| {
            let focused_tab = self.app.main_ui.tree.tiles.get_mut(
                self.app.additional_ui.focused_id.unwrap_or(TileId::default())
            ).and_then(|p| {
                if let Tile::Pane(pane) = p { Some(pane) } else { None }
            });
            let Some(ref mut focused) = focused_tab else {
                ui.label(tr!("menu-nothing-focused"));
                return;
            };
            match *tab {
                AdditionalTab::Edit => for_all_tabs!(focused, t, t.edit_display(self.app, ui)),
                AdditionalTab::Properties => for_all_tabs!(focused, t, t.display_display(self.app, ui)),
                AdditionalTab::Export => for_all_tabs!(focused, t, t.export_display(self.app, ui)),
            }
        });
        Default::default()
    }
}

