pub fn show_ui(
    ui: &mut Ui,
    app: &mut tabs::AppState,
    cpu_time: Option<f32>,
) {
    // Handle modal
    if let Some(m) = &mut app.modal.0 {
        let modal_response = egui::Modal::new(m.id()).show(ui.ctx(), |ui| m.display(ui, app));
        if modal_response.should_close() { app.modal.0 = None }
    }

    // command palette
    world.resource_scope(|world, mut command_palette: Mut<command_palette::CommandPalette>| {
        if ui.input_mut(|r| r.consume_shortcut(&KeyboardShortcut::new(Modifiers::CTRL, Key::P))) {
            command_palette.toggle();
        };
        command_palette.show(ui.ctx(), app);
    });

    Panel::top("top panel").exact_size(32.0).show_inside(ui, |ui| {
        ui.with_layout(egui::Layout::left_to_right(egui::Align::Center), |ui| {
            let res = ui.button("More...");
            #[cfg(not(target_arch = "wasm32"))]
            if ui.button("Fullscreen").clicked() {
                let is_fullscreen = ui.input(|i| i.viewport().fullscreen.unwrap_or(false));
                ui.send_viewport_cmd(egui::ViewportCommand::Fullscreen(!is_fullscreen));
            }
            #[cfg(target_arch = "wasm32")]
            if ui.button("Fullscreen").clicked() { toggle_fullscreen("paiagram_canvas"); }
            egui::Popup::menu(&res).show(|ui| {
                if ui.button("Import from URL...").clicked() {
                    app.modal.0 = Some(Modals::OpenUrl(String::new()));
                }
                ui.separator();
                // Import file buttons
                let mut read_file = |name: &str, ext: &str| {
                    if ui.button(tr!("read-file-prompt", {name: name})).clicked() {
                        // TODO: re-implement file reading via rfd
                    }
                };
                read_file("OuDia", ".oud");
                read_file("OuDiaSecond", ".oud2");
                read_file("qETRC/pyETRC", ".pyetgr");
                read_file("GTFS", ".zip");
                read_file("LLT", ".json");
                ui.separator();
                if ui.button("Save...").clicked() { save::save(app); }
                if ui.button("Read...").clicked() { save::load(app); }
                if app.preferences.developer_mode && ui.button("Save RON...").clicked() {
                    save::save_ron(app);
                }
                if app.preferences.developer_mode && ui.button("Read RON...").clicked() {
                    save::load_ron(app);
                }
            });
            let res = ui.button(tr!("menu-about"));
            egui::Popup::menu(&res).show(|ui| {
                if ui.button(tr!("menu-documentation")).clicked() {
                    ui.ctx().open_url(OpenUrl::new_tab(
                        if cfg!(target_arch = "wasm32") { "/docs" } else { "https://paiagram.com/docs" }
                    ));
                }
                if cfg!(target_arch = "wasm32") && ui.button(tr!("menu-legal")).clicked() {
                    ui.ctx().open_url(OpenUrl::new_tab("./license.html"));
                }
            });
            // FPS counter
            if app.preferences.developer_mode {
                app.frame_time_history.push(ui.input(|r| r.stable_dt));
                let average_dt = app.frame_time_history.average_dt();
                ui.monospace(format!("FPS: {:6.2}", 1.0_f32 / average_dt));
                ui.monospace(format!("FRAME: {:5.2}ms", average_dt * 1000.0_f32));
                ui.monospace(format!("CPU: {:5.2}ms", cpu_time.unwrap_or(0.0) * 1000.0_f32));
                ui.horizontal(|ui| {
                    const GAP: f32 = 4.0;
                    const SAMPLE_COUNT: usize = 32;
                    let stroke = Stroke { color: PredefinedColor::Blue.get(ui.visuals().dark_mode), width: 3.0 };
                    let max = app.frame_time_history.previous_n(SAMPLE_COUNT).fold(0.0_f32, f32::max).max(f32::EPSILON);
                    let graph_width = SAMPLE_COUNT as f32 * (stroke.width + GAP) - GAP;
                    let graph_height = ui.available_height();
                    let (rect, _) = ui.allocate_exact_size(egui::vec2(graph_width, graph_height), egui::Sense::hover());
                    for (idx, f) in app.frame_time_history.previous_n(SAMPLE_COUNT).enumerate() {
                        let height = rect.height() * (f / max).clamp(0.0, 1.0);
                        let x = rect.right() - idx as f32 * (stroke.width + GAP) - stroke.width * 0.5;
                        let points = [egui::pos2(x, rect.bottom()), egui::pos2(x, rect.bottom() - height)];
                        ui.painter().line_segment(points, stroke);
                    }
                });
            }
            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                if ui.add_enabled(app.source.undoable(), egui::Button::new(tr!("menu-undo"))).clicked() {
                    app.source.undo();
                }
                if ui.add_enabled(app.source.redoable(), egui::Button::new(tr!("menu-redo"))).clicked() {
                    app.source.redo();
                }
                ui.checkbox(&mut app.additional_ui.expanded, "");
            });
        })
    });

    Panel::bottom("bottom panel").exact_size(24.0).show_inside(ui, |ui| {
        ui.horizontal_centered(|ui| {
            let ticks_in_cycle = app.project_settings.repeat_frequency.to_ticks();
            let mut time = app.timer.read_ticks().to_timetable_time();
            ui.add_enabled(!app.timer.sync_to_real_time, egui::Checkbox::new(&mut app.timer.animation_playing, ""));
            let time_response = ui.add(TimeDragValue(&mut time));
            ui.add_enabled(!app.timer.sync_to_real_time, egui::DragValue::new(&mut app.timer.animation_speed).fixed_decimals(1).suffix("×"));
            egui::Popup::menu(&time_response).show(|ui| {
                ui.checkbox(&mut app.timer.sync_to_real_time, tr!("menu-sync-system-clock"));
            });
            if !app.timer.sync_to_real_time && time_response.dragged() && app.timer.try_lock() {
                app.timer.write_ticks(Tick::from_timetable_time(time));
            } else {
                app.timer.try_unlock();
            }
            if app.timer.animation_playing { ui.ctx().request_repaint(); }

            // cycle progress bar
            let (_id, rect) = ui.allocate_space(ui.available_size());
            let progress_stroke = ui.visuals().window_stroke();
            ui.painter().hline(rect.x_range(), rect.center().y, progress_stroke);
            let amount_of_ticks = 24;
            for i in 0..(amount_of_ticks + 1) {
                let progress = (1.0 / amount_of_ticks as f32) * i as f32;
                let x = rect.left().lerp(rect.right(), progress);
                let y_range = if i % 4 == 0 { rect.y_range() } else { rect.y_range().shrink(5.0) };
                ui.painter().vline(x, y_range, progress_stroke);
            }

