//! Save/load functionality using the core's serialization.

use paiagram_core::{SaveFile, Source};

/// The data we persist to disk.
#[derive(serde::Serialize, serde::Deserialize)]
pub(crate) struct SaveData {
    pub(crate) source: Source,
    // UI state that should survive restart
    pub(crate) main_ui_state: Option<crate::MainUiState>,
    pub(crate) timer: Option<crate::GlobalTimer>,
    pub(crate) project_settings: Option<paiagram_core::settings::ProjectSettings>,
}

pub(crate) fn save(app: &mut crate::tabs::AppState, filename: String) {
    let data = SaveData {
        source: std::mem::take(&mut app.source),
        main_ui_state: Some(app.main_ui.clone()),
        timer: Some(app.timer.clone()),
        project_settings: Some(app.project_settings.clone()),
    };
    paiagram_rw::save::serialize_compressed_cbor(
        SaveFile::V1 {
            world: data.source.clone().into(),
        },
        filename,
    );
}

pub(crate) fn save_ron(app: &mut crate::tabs::AppState, filename: String) {
    let data = SaveData {
        source: std::mem::take(&mut app.source),
        main_ui_state: Some(app.main_ui.clone()),
        timer: Some(app.timer.clone()),
        project_settings: Some(app.project_settings.clone()),
    };
    paiagram_rw::save::serialize_ron(
        SaveFile::V1 {
            world: data.source.clone().into(),
        },
        filename,
    );
}

pub(crate) fn apply_loaded_scene(app: &mut crate::tabs::AppState, bytes: &[u8]) -> Result<(), String> {
    let save: SaveFile = cbor4ii::serde::from_slice(bytes).map_err(|e| format!("CBOR decode error: {e}"))?;
