use egui::Ui;
use egui_i18n::tr;
use serde::{Deserialize, Serialize};

use super::{AppState, Tab};

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Default)]
pub(crate) struct StartTab;

impl Tab for StartTab {
    const NAME: &'static str = "Start";
    fn main_display(&mut self, app: &mut AppState, ui: &mut Ui) {
        ui.heading(tr!("program-name"));
        egui::Grid::new("start info grid")
            .num_columns(2)
            .show(ui, |ui| {
                ui.label(tr!("tab-start-amount-vehicles"));
                ui.label(app.source.vehicles.len().to_string());
                ui.end_row();
                ui.label(tr!("tab-start-amount-trips"));
                ui.label(app.source.trips.len().to_string());
                ui.end_row();
                ui.label(tr!("tab-start-amount-stations"));
                ui.label(app.source.stations.len().to_string());
                ui.end_row();
                ui.label(tr!("tab-start-amount-routes"));
                ui.label(app.source.routes.len().to_string());
                ui.end_row();
                ui.label(tr!("tab-start-amount-intervals"));
                ui.label(app.source.intervals.len().to_string());
            });
        if ui.button(tr!("tab-start-merge-stations-by-name")).clicked() {
            // TODO: implement station merge
        }
    }
    fn title(&self) -> egui::WidgetText {
        tr!("tab-start").into()
    }
    fn scroll_bars(&self) -> [bool; 2] {
        [false, true]
    }
}

use egui::Ui;
use egui_i18n::tr;
use paiagram_core::i18n::Language;
use paiagram_core::settings::{AntialiasingMode, LevelOfDetailMode};
use serde::{Deserialize, Serialize};

use super::{AppState, Tab};

#[derive(Serialize, Deserialize, Clone, Default, PartialEq)]
pub(crate) struct SettingsTab;

impl Tab for SettingsTab {
    const NAME: &'static str = "Settings";
    fn main_display(&mut self, app: &mut AppState, ui: &mut Ui) {
        ui.heading(tr!("settings-preferences"));
        egui::Grid::new("settings grid 1").show(ui, |ui| {
            ui.label(tr!("settings-dark-mode"));
            ui.checkbox(&mut app.preferences.dark_mode, "");
            ui.end_row();

            ui.label(tr!("settings-language"));
            egui::ComboBox::new("language", "")
                .selected_text(app.preferences.lang.clone())
                .show_ui(ui, |ui| {
                    for lang in Language::ALL {
                        let selected = app.preferences.lang == lang;
                        ui.selectable_value(&mut app.preferences.lang, lang.to_string(), lang.name());
                    }
                });
            ui.end_row();

            ui.label(tr!("settings-developer-mode"));
            ui.checkbox(&mut app.preferences.developer_mode, "");
            ui.end_row();

            ui.label(tr!("settings-antialiasing-options"));
            egui::ComboBox::new("antialiasing", "")
                .selected_text(match app.preferences.antialiasing_mode {
                    AntialiasingMode::Off => tr!("settings-off"),
                    AntialiasingMode::On => tr!("settings-on"),
                })
                .show_ui(ui, |ui| {
                    ui.selectable_value(
                        &mut app.preferences.antialiasing_mode,
                        AntialiasingMode::Off,
                        tr!("settings-off"),
                    );
                    ui.selectable_value(
                        &mut app.preferences.antialiasing_mode,
                        AntialiasingMode::On,
                        tr!("settings-on"),
                    );
                });
            ui.end_row();

            ui.label(tr!("settings-lod-mode"));
            egui::ComboBox::new("lod", "")
                .selected_text(match app.preferences.level_of_detail_mode {
                    LevelOfDetailMode::Off => tr!("settings-off"),
                    LevelOfDetailMode::Lod2 => tr!("settings-lod-2x"),
                    LevelOfDetailMode::Lod4 => tr!("settings-lod-4x"),
                })
                .show_ui(ui, |ui| {
                    ui.selectable_value(
                        &mut app.preferences.level_of_detail_mode,
                        LevelOfDetailMode::Off,
                        tr!("settings-off"),
                    );
                    ui.selectable_value(
                        &mut app.preferences.level_of_detail_mode,
                        LevelOfDetailMode::Lod2,
                        tr!("settings-lod-2x"),
                    );
                    ui.selectable_value(
                        &mut app.preferences.level_of_detail_mode,
                        LevelOfDetailMode::Lod4,
                        tr!("settings-lod-4x"),
                    );
                });
            ui.end_row();
        });
        ui.heading(tr!("settings-project-settings"));
        ui.text_edit_multiline(&mut app.project_settings.remarks);
    }
    fn title(&self) -> egui::WidgetText {
        tr!("tab-settings").into()
    }
}

use std::sync::Arc;

use egui::Ui;
use serde::{Deserialize, Serialize};

use super::{AppState, Tab};

#[derive(Clone, Serialize, Deserialize, Default, PartialEq)]
pub(crate) struct TextMessage(pub(crate) String);

#[derive(Serialize, Deserialize, Clone, PartialEq)]
pub(crate) struct TextTab {
    message: Option<Arc<TextMessage>>,
    // If message is None, show project remarks
}

impl TextTab {
    pub(crate) fn new(message_id: Option<usize>) -> Self {
        // message_id was Entity in old code; now we just pass a placeholder
        Self { message: None }
    }
}

impl Default for TextTab {
    fn default() -> Self {
        Self { message: None }
    }
}

impl Tab for TextTab {
    const NAME: &'static str = "Text";
    fn title(&self) -> egui::WidgetText {
        "Text".into()
    }
    fn main_display(&mut self, app: &mut AppState, ui: &mut Ui) {
        egui::ScrollArea::vertical().show(ui, |ui| {
            if self.message.is_some() {
                // TODO: show the message
                ui.label("Message placeholder");
            } else {
                // Show project remarks
                ui.heading("Project Remarks");
                ui.text_edit_multiline(&mut app.project_settings.remarks);
            }
        });
    }
}

use egui::{Button, Layout, Panel, ScrollArea, Ui, WidgetText, vec2};
use egui_i18n::tr;
use paiagram_core::ClassKey;
use serde::{Deserialize, Serialize};

use super::{AppState, Tab};
use crate::MainTab;
use crate::tabs::trip::TripTab;

#[derive(Default, PartialEq, Clone, Serialize, Deserialize)]
pub(crate) struct ClassesTab {
    #[serde(skip)]
    selected_class: Option<ClassKey>,
}

impl Tab for ClassesTab {
    const NAME: &'static str = "Classes";
    fn title(&self) -> WidgetText {
        tr!("tab-classes").into()
    }
    fn main_display(&mut self, app: &mut AppState, ui: &mut Ui) {
        Panel::right(ui.id().with("first"))
            .default_size(ui.available_width() / 3.0)
            .resizable(true)
            .show_inside(ui, |ui| {
                ScrollArea::vertical().show(ui, |ui| {
                    ui.label("Trips");
                    let Some(class_key) = self.selected_class else {
                        return;
                    };
                    let class_view = app.source.classes.get_view(class_key);
                    let Some(_view) = class_view else {
                        return;
                    };
                    ui.with_layout(Layout::default().with_cross_justify(true), |ui| {
                        // Show trips with this class
                        for (tk, name) in app.source.trips_iter() {
                            let has_class = app.source.trips.query(tk, |b| *b.class == Some(class_key)).unwrap_or(false);
                            if !has_class { continue; }
                            let res = ui.button(name.as_str());
                            if res.clicked() {
                                app.main_ui.push_to_focused_leaf(MainTab::Trip(TripTab::new(tk)));
                            }
                        }
                    });
                });
            });

        let mut itoa_buffer = itoa::Buffer::new();
        ScrollArea::vertical().auto_shrink(false).show(ui, |ui| {
            egui::Grid::new("class grid")
                .num_columns(3)
                .striped(true)
                .show(ui, |ui| {
                    ui.label(tr!("classes-name"));
                    ui.label(tr!("classes-count"));
                    ui.label(tr!("classes-color"));
                    ui.end_row();
                    for ck in app.source.classes.keys() {
                        let view = app.source.classes.get_view(*ck);
                        let Some(ref view) = view else { continue; };
                        ui.allocate_ui_with_layout(
                            vec2(200.0, 24.0),
                            Layout::default().with_cross_justify(true),
                            |ui| {
                                let mut is_sel = self.selected_class == Some(*ck);
                                if ui.selectable_value(&mut is_sel, true, view.name.as_str()).clicked() {
                                    self.selected_class = Some(*ck);
                                }
                                if !is_sel && self.selected_class == Some(*ck) {
                                    self.selected_class = None;
                                }
                            },
                        );
                        let printed = itoa_buffer.format(count_trips_with_class(app, *ck));
                        ui.label(printed);
                        let mut displayed_color: paiagram_core::colors::DisplayedColor = 
                            paiagram_core::colors::DisplayedColor::Custom(view.style.color);
                        ui.add(&mut displayed_color);
                        ui.end_row();
                    }
                });
        });
    }
}

fn count_trips_with_class(app: &AppState, class_key: ClassKey) -> usize {
    app.source.trips.keys().filter(|tk| {
        app.source.trips.query(**tk, |b| *b.class == Some(class_key)).unwrap_or(false)
    }).count()
}

use egui::{Color32, Rect, RichText, Stroke, WidgetText};
use egui_i18n::tr;
use paiagram_core::StationKey;
use paiagram_core::units::time::TimetableTime;
use serde::{Deserialize, Serialize};

use super::{AppState, Tab};
use crate::widgets::indicators::{
    display_time_indicator_indicator_horizontal, display_time_indicator_indicator_vertical,
};

#[derive(Serialize, Deserialize, Clone, PartialEq)]
pub(crate) struct StationTab {
    station_key: StationKey,
    include_nonstop: bool,
}

impl StationTab {
    pub(crate) fn new(station_key: StationKey) -> Self {
        Self { station_key, include_nonstop: false }
    }
}

impl super::Tab for StationTab {
    const NAME: &'static str = "Station";
    fn title(&self) -> WidgetText {
        tr!("tab-station").into()
    }
    fn main_display(&mut self, app: &mut AppState, ui: &mut egui::Ui) {
        let station_name = app.source.stations.query(self.station_key, |b| b.name.clone())
            .unwrap_or_default();
        ui.heading(station_name.as_str());
        ui.checkbox(&mut self.include_nonstop, tr!("station-include-non-stop"));
        egui::ScrollArea::both().show(ui, |ui| {
            display_time_grid(self, app, ui);
        });
    }
}

fn display_time_grid(tab: &StationTab, app: &AppState, ui: &mut egui::Ui) {
    // Build list of passing trips/entries through this station
    #[derive(Clone)]
    struct DisplayedEntry {
        time: TimetableTime,
        color: Color32,
        trip_name: String,
        last_station_name: String,
    }

    let mut entry_bucket: [Vec<DisplayedEntry>; 24] = [const { Vec::new() }; 24];

    // Scan all trips for entries at this station
    for tk in app.source.trips.keys() {
        let trip_view = app.source.trips.get_view(*tk);
        let Some(ref view) = trip_view else { continue; };

        for (entry_idx, entry) in view.schedule.entries().iter().enumerate() {
            let stn_key = match entry {
                paiagram_core::trip::TEntry::Derived(s) => *s,
                paiagram_core::trip::TEntry::Pinned { stn: s, .. } => *s,
                paiagram_core::trip::TEntry::PinnedNonStop { stn: s, .. } => *s,
                paiagram_core::trip::TEntry::PinnedExternalNonStop { stn: s, .. } => *s,
                paiagram_core::trip::TEntry::PinnedExternal { .. } => continue,
            };

            if stn_key != tab.station_key { continue; }

            // Get departure estimate
            let dep_time = match entry {
                paiagram_core::trip::TEntry::Pinned { dep, .. } => match dep {
                    paiagram_core::trip::TravelMode::At(t) => *t,
                    paiagram_core::trip::TravelMode::For(d) => {
                        // For "For" duration, we need the arrival time + duration
                        // For simplicity, just use a rough estimate
                        TimetableTime(0)
                    }
                    paiagram_core::trip::TravelMode::Flexible => continue,
                },
                paiagram_core::trip::TEntry::Derived(_) => continue,
                _ => continue,
            };

            if !tab.include_nonstop {
                // Skip entries without an arrival mode (non-stop)
                let has_arr = matches!(entry, paiagram_core::trip::TEntry::Pinned { .. });
                if !has_arr { continue; }
            }

            // Find last station name
            let last_station_name = view.schedule.entries().last()
                .and_then(|last| match last {
                    paiagram_core::trip::TEntry::Derived(s) | 
                        paiagram_core::trip::TEntry::Pinned { stn: s, .. } |
                        paiagram_core::trip::TEntry::PinnedNonStop { stn: s, .. } |
                        paiagram_core::trip::TEntry::PinnedExternalNonStop { stn: s, .. } => {
                        app.source.stations.query(*s, |b| b.name.clone())
                    }
                    _ => None,
                })
                .unwrap_or_default();

            // Get class color
            let color = view.class
                .and_then(|ck| app.source.classes.get_view(ck))
                .map(|cv| cv.style.color)
                .unwrap_or(Color32::GRAY);

            entry_bucket[dep_time.hour() as usize].push(DisplayedEntry {
                time: dep_time,
                color,
                trip_name: view.name.to_string(),
                last_station_name: last_station_name.to_string(),
            });
        }
    }

    for line in entry_bucket.iter_mut() {
        line.sort_by_key(|it| it.time.minute() * 60 + it.time.second());
    }

    let mut heights: [f32; 25] = [0.0; 25];
    let (current_h, current_min, current_secs, _) =
        app.timer.read_ticks().to_timetable_time().to_hmsd();
    let current_h = current_h as usize;
    let mut widths_seconds: Vec<(f32, i32)> = Vec::with_capacity(entry_bucket[current_h].len() + 2);
    widths_seconds.push((ui.clip_rect().left(), 0));

    egui::Grid::new("station grid")
        .striped(true)
        .show(ui, |ui| {
            for (line_idx, entries) in entry_bucket.into_iter().enumerate() {
                ui.horizontal_centered(|ui| {
                    ui.heading(line_idx.to_string());
                });
                fn display_entry(entry: DisplayedEntry, ui: &mut egui::Ui) {
                    ui.vertical_centered(|ui| {
                        ui.small(entry.last_station_name);
                        ui.label(
                            RichText::new(entry.time.minute().to_string())
                                .color(entry.color)
                                .font(egui::FontId::new(
                                    16.0,
                                    egui::FontFamily::Name("dia_pro".into()),
                                )),
                        );
                        ui.small(entry.trip_name);
                    });
                }
                if line_idx == current_h {
                    let mut push_widths_seconds = |minutes: i32, ui: &egui::Ui| {
                        if widths_seconds.last().unwrap().1 == minutes * 60 { return; }
                        widths_seconds.push((ui.cursor().left(), minutes * 60));
                    };
                    for entry in entries {
                        push_widths_seconds(entry.time.minute(), ui);
                        display_entry(entry, ui);
                    }
                    push_widths_seconds(60, ui);
                } else {
                    for entry in entries {
                        display_entry(entry, ui);
                    }
                }
                heights[line_idx] = ui.cursor().top();
                ui.end_row();
            }
        });
    heights[24] = ui.cursor().top();

    // Time indicators
    let current_seconds = current_min * 60 + current_secs;
    let hour_progress = current_seconds as f32 / 3600.0;
    let base_y = heights[current_h];
    let next_y = heights[current_h + 1];
    let block_height = next_y - base_y;
    let mut hour_line_y = base_y + block_height * hour_progress;
    let (base_x_idx, (base_x, base_seconds)) = widths_seconds
        .iter()
        .enumerate()
        .rev()
        .find(|(_, (_, secs))| current_seconds >= *secs)
        .unwrap_or((0, &(0.0, 0)));
    let (next_x, next_seconds) = if base_x_idx + 1 < widths_seconds.len() {
        widths_seconds[base_x_idx + 1]
    } else {
        (base_x, base_seconds + 3600)
    };
    let width = next_x - base_x;
    let width_seconds = next_seconds - base_seconds;
    let minute_progress = if width_seconds > 0 {
        (current_seconds - base_seconds) as f32 / (width_seconds) as f32
    } else {
        0.0
    };
    let mut minute_line_x = base_x + width * minute_progress;
    let line_stroke = Stroke::new(1.5, Color32::RED);
    line_stroke.round_center_to_pixel(ui.pixels_per_point(), &mut hour_line_y);
    line_stroke.round_center_to_pixel(ui.pixels_per_point(), &mut minute_line_x);

    display_time_indicator_indicator_vertical(
        ui.id().with("hour indicator"),
        ui.clip_rect(),
        hour_line_y,
        line_stroke.color,
        ui.painter(),
    );
    ui.painter().hline(
        ui.clip_rect().left()..=ui.clip_rect().right(),
        hour_line_y,
        line_stroke,
    );
    display_time_indicator_indicator_horizontal(
        ui.id().with("minute indicator"),
        Rect::from_x_y_ranges(ui.clip_rect().x_range(), base_y..=next_y),
        minute_line_x,
        line_stroke.color,
        ui.painter(),
    );
    ui.painter().vline(minute_line_x, base_y..=next_y, line_stroke);
}

use ecow::EcoVec;
use egui::{Color32, RectAlign, Ui, Vec2, WidgetText, vec2};
use egui_i18n::tr;
use paiagram_core::trip::{TEntry, TravelMode};
use paiagram_core::units::time::{Duration, TimetableTime};
use paiagram_core::{Command, TripKey};
use serde::{Deserialize, Serialize};

use super::{AppState, Tab};

#[derive(Serialize, Deserialize, Clone, PartialEq)]
pub(crate) struct TripTab {
    trip_key: TripKey,
}

impl TripTab {
    pub(crate) fn new(trip_key: TripKey) -> Self {
        Self { trip_key }
    }
}

impl Tab for TripTab {
    const NAME: &'static str = "Trip";
    fn title(&self) -> WidgetText {
        tr!("tab-trip").into()
    }
    fn main_display(&mut self, app: &mut AppState, ui: &mut egui::Ui) {
        let view = app.source.trips.get_view(self.trip_key);
        let Some(ref view) = view else {
            ui.label("Trip not found");
            return;
        };

        ui.heading(view.name.as_str());
        let entry_count = view.schedule.entries().len();
        ui.label(entry_count.to_string());

        let mut entries: Vec<(usize, &TEntry)> = view.schedule.entries().iter().enumerate().collect();

        egui::ScrollArea::vertical().show(ui, |ui| {
            egui::Grid::new(ui.id().with("trip_grid"))
                .num_columns(3)
                .striped(true)
                .show(ui, |ui| {
                    ui.label(tr!("trip-table-station"));
                    ui.label(tr!("trip-table-arrival"));
                    ui.label(tr!("trip-table-departure"));
                    ui.end_row();
                    for (idx, entry) in entries.iter() {
                        let stn_name = get_station_name(app, entry);
                        ui.label(stn_name);

                        let (arr, dep) = get_entry_times(entry);

                        // Arrival
                        if let Some(arr_time) = arr {
                            let mut t = arr_time;
                            let res = ui.add_sized(vec2(70.0, 18.0), crate::widgets::TimeDragValue(&mut t));
                            if res.changed() && t != arr_time {
                                modify_entry_time(app, self.trip_key, *idx, true, t - arr_time);
                            }
                        } else {
                            ui.label("↓");
                        }

                        // Departure
                        let dep_time = dep;
                        let mut t = dep_time;
                        let res = ui.add_sized(vec2(70.0, 18.0), crate::widgets::TimeDragValue(&mut t));
                        if res.changed() && t != dep_time {
                            modify_entry_time(app, self.trip_key, *idx, false, t - dep_time);
                        }

                        ui.end_row();
                    }
                });
        });
    }
}

fn get_station_name(app: &AppState, entry: &TEntry) -> String {
    let sk = match entry {
        TEntry::Derived(s) => *s,
        TEntry::Pinned { stn: s, .. } => *s,
        TEntry::PinnedNonStop { stn: s, .. } => *s,
        TEntry::PinnedExternalNonStop { stn: s, .. } => *s,
        TEntry::PinnedExternal { .. } => return "External".into(),
    };
    app.source.stations.query(sk, |b| b.name.clone())
        .unwrap_or_default()
        .to_string()
}

fn get_entry_times(entry: &TEntry) -> (Option<TimetableTime>, TimetableTime) {
    match entry {
        TEntry::Pinned { arr: TravelMode::At(a), dep, .. } => {
            let dep_t = match dep {
                TravelMode::At(t) => *t,
                TravelMode::For(d) => *a + *d,
                TravelMode::Flexible => *a,
            };
            (Some(*a), dep_t)
        }
        TEntry::Pinned { dep: TravelMode::At(t), .. } => (None, *t),
        TEntry::Pinned { dep: TravelMode::For(d), arr, .. } => {
            let base = match arr {
                Some(TravelMode::At(a)) => *a,
                _ => TimetableTime(0),
            };
            (None, base + *d)
        }
        TEntry::PinnedNonStop { pass: TravelMode::At(t), .. } => (None, *t),
        TEntry::PinnedNonStop { pass: TravelMode::For(d), .. } => (None, *d + TimetableTime(0)),
        _ => (None, TimetableTime(0)),
    }
}

fn modify_entry_time(app: &mut AppState, trip_key: TripKey, entry_idx: usize, is_arrival: bool, delta: Duration) {
    let view = app.source.trips.get_view(trip_key);
    let Some(view) = view else { return; };

    let mut entries: Vec<TEntry> = view.schedule.entries().to_vec();
    if entry_idx >= entries.len() { return; }

    let modified = match &entries[entry_idx] {
        TEntry::Pinned { stn, trk, arr, dep, id } => {
            let new_arr = if is_arrival {
                match arr {
                    TravelMode::At(t) => Some(TravelMode::At(*t + delta)),
                    TravelMode::For(d) => Some(TravelMode::For(*d + delta)),
                    TravelMode::Flexible => Some(TravelMode::Flexible),
                }
            } else {
                Some(*arr)
            };
            let new_dep = if !is_arrival {
                match dep {
                    TravelMode::At(t) => TravelMode::At(*t + delta),
                    TravelMode::For(d) => TravelMode::For(*d + delta),
                    TravelMode::Flexible => TravelMode::Flexible,
                }
            } else {
                *dep
            };
            TEntry::Pinned { stn: *stn, trk: *trk, arr: new_arr.unwrap_or(*arr), dep: new_dep, id: *id }
        }
        _ => entries[entry_idx].clone(),
    };
    entries[entry_idx] = modified;

    app.source.apply_command(Command::ChangeTripEntries {
        key: trip_key,
        entries: entries.into(),
    });
}

use egui::{FontId, Layout, Rect, RichText, Ui, Vec2, WidgetText, vec2};
