#[derive(Serialize, Deserialize, Clone, PartialEq)]
pub(crate) struct GraphTab {
    navi: GraphNavigation,
    arrange_iterations: u32,
    osm_area_name: String,
}

impl Default for GraphTab {
    fn default() -> Self {
        Self {
            navi: GraphNavigation::default(),
            arrange_iterations: 1000,
            osm_area_name: String::new(),
        }
    }
}

#[derive(Serialize, Deserialize, Clone)]
pub(crate) struct GraphNavigation {
    x_offset: f64,
    y_offset: f64,
    zoom: f32,
    visible: egui::Rect,
}

impl Default for GraphNavigation {
    fn default() -> Self {
        Self { x_offset: 0.0, y_offset: 0.0, zoom: 1.0, visible: egui::Rect::NOTHING }
    }
}

impl Navigatable for GraphNavigation {
    type XOffset = f64;
    type YOffset = f64;
    fn zoom_x(&self) -> f32 { self.zoom }
    fn zoom_y(&self) -> f32 { self.zoom }
    fn set_zoom(&mut self, zoom_x: f32, _zoom_y: f32) { self.zoom = zoom_x; }
    fn offset_x(&self) -> f64 { self.x_offset }
    fn offset_y(&self) -> f64 { self.y_offset }
    fn set_offset(&mut self, offset_x: f64, offset_y: f64) { self.x_offset = offset_x; self.y_offset = offset_y; }
    fn visible_rect(&self) -> egui::Rect { self.visible }
}

impl Tab for GraphTab {
    const NAME: &'static str = "Graph";
    fn title(&self) -> WidgetText { tr!("tab-graph").into() }
    fn main_display(&mut self, app: &mut AppState, ui: &mut egui::Ui) {
        egui::Frame::canvas(ui.style())
            .inner_margin(Margin::ZERO)
            .outer_margin(Margin::ZERO)
            .stroke(Stroke::NONE)
            .show(ui, |ui| display(self, app, ui));
    }
    fn edit_display(&mut self, app: &mut AppState, ui: &mut egui::Ui) {
        ui.add(egui::Slider::new(&mut self.arrange_iterations, 100..=10000)
            .text(tr!("tab-graph-auto-arrange-iterations")));
        if ui.button(tr!("tab-graph-auto-arrange")).clicked() {
            // TODO: implement auto-arrange with core types
        }
        ui.separator();
        ui.horizontal(|ui| {
            ui.label(tr!("tab-graph-osm-area-name"));
            ui.text_edit_singleline(&mut self.osm_area_name);
        });
        if ui.button(tr!("tab-graph-arrange-via-osm")).clicked() {
            // TODO: implement OSM-based arrangement
        }
        ui.separator();
        if let SelectedItems::Stations(stations) = &app.selected_items {
            for sel in stations {
                if let Some(name) = app.source.stations.query(sel.station, |b| b.name.clone()) {
                    ui.label(name.as_str());
                }
            }
            let res = ui.button(tr!("graph-create-new-route"));
            if res.clicked() && stations.len() >= 2 {
                let stops: Vec<_> = stations.iter().map(|s| s.station).collect();
                let rk = paiagram_core::RouteKey::new();
                app.source.apply_command(paiagram_core::Command::AddRoute {
                    key: rk,
                    view: paiagram_core::RouteView {
                        name: "New Route".into(),
                        stations: stops.into(),
                    },
                });
            }
        }
    }
}

fn display(tab: &mut GraphTab, app: &mut AppState, ui: &mut egui::Ui) {
    let (response, mut painter) =
        ui.allocate_painter(ui.available_size_before_wrap(), Sense::click_and_drag());
    tab.navi.visible = response.rect;
    tab.navi.handle_navigation(ui, &response);

    let is_dark = ui.visuals().dark_mode;
    let color = PredefinedColor::Neutral.get(is_dark);

    // Draw intervals (graph edges)
    for ik in app.source.intervals.keys() {
        if let Some(view) = app.source.intervals.get_view(*ik) {
            let nodes = &view.nodes;
            for pair in nodes.windows(2) {
                let p0 = pair[0];
                let p1 = pair[1];
                let spos = tab.navi.xy_to_screen_pos(p0.lon as f64, p0.lat as f64);
                let tpos = tab.navi.xy_to_screen_pos(p1.lon as f64, p1.lat as f64);
                painter.line_segment([spos, tpos], Stroke::new(1.0, color));
            }
        }
    }

    // Draw stations
    let interact_pos = response.clicked()
        .then(|| ui.input(|r| r.pointer.interact_pos()))
        .flatten();

    for sk in app.source.stations.keys() {
        if let Some(view) = app.source.stations.get_view(*sk) {
            let pos = view.pos;
            let spos = tab.navi.xy_to_screen_pos(pos.lon as f64, pos.lat as f64);
            painter.circle_filled(spos, 4.0, color);

            // Check for click
            if let Some(ipos) = interact_pos {
                if (spos - ipos).length() < 10.0 {
                    let sel = station_click_interaction(app, sk, ui);
                    if sel {
                        // handled
                    }
                }
            }

            // Draw name
            painter.text(
                spos + egui::vec2(7.0, 0.0),
                Align2::LEFT_CENTER,
                view.name.as_str(),
                FontId::proportional(13.0),
                color,
            );
        }
    }
}

fn station_click_interaction(app: &mut AppState, sk: &StationKey, ui: &egui::Ui) -> bool {
    let shift_pressed = ui.input(|r| r.modifiers.shift);
    let command_pressed = ui.input(|r| r.modifiers.command);
    let sel = SelectedItem::Station(StationSelection { station: *sk });
    if command_pressed {
        app.selected_items.toggle_selection(sel);
    } else if !shift_pressed {
        app.selected_items.set_single_selection(sel);
    }
    true
}

