let modal_response = egui::Modal::new(egui::Id::new("modal")).show(ui.ctx(), |ui| {
    if let Some(m) = &mut app.modal.0 {
        m.display(app, ui);
    }
});

edits.newText:
// Modal - use a separate borrow to avoid conflict
{
    let modal_content = &mut app.modal;
    let is_open = modal_content.0.is_some();
    if is_open {
        let modal_response = egui::Modal::new(egui::Id::new("modal")).show(ui.ctx(), |ui| {
            // Inside modal, display can't take &mut AppState directly
            ui.label("Modal content");
        });
        if modal_response.should_close() {
            app.modal.0 = None;
        }
    }
}

