/// Languages
/// Sorted alphabetically
#[derive(Reflect, Clone, Copy, Debug, PartialEq, Eq, Default)]
pub enum Language {
    #[default]
    EnCA,
    JaJP,
    ZhHans,
}

impl Language {
    pub const ALL: &[Self] = &[Self::EnCA, Self::JaJP, Self::ZhHans];
    /// The native name of the language.
    pub fn name(self) -> &'static str {
        match self {
            Self::EnCA => "English (Canada)",
            Self::JaJP => "Japanese",
            Self::ZhHans => "中文（简体）",
        }
    }
    /// The identifier of the language.
    pub fn identifier(self) -> &'static str {
        match self {
            Self::EnCA => "en-CA",
            Self::JaJP => "ja-JP",
            Self::ZhHans => "zh-Hans",
        }
    }
    /// Set the localization
    pub fn set(&mut self, identifier: &str) -> bool {
        for lang in Self::ALL {
            if identifier != lang.identifier() {
                continue;
            }
            *self = *lang;
            return true;
        }
        false
    }
}

pub fn init() {
    let default_identifier = Language::default().identifier();
    // TODO: move these strings
    load_translations_from_text(
        default_identifier,
        include_str!("../../paiagram/assets/locales/en-CA.ftl"),
    )
    .unwrap();
    load_translations_from_text(
        "zh-Hans",
        include_str!("../../paiagram/assets/locales/zh-Hans.ftl"),
    )
    .unwrap();
    set_language(default_identifier);
    set_fallback(default_identifier);
}

