fn render_central_panel(app: &mut AppState, ui: &mut egui::Ui, maximized: &mut Option<TileId>) {
    if let Some(max_id) = app.main_ui.maximized {
        // For maximized view, clone the tab data to avoid borrow conflicts
        if let Some(Tile::Pane(pane)) = app.main_ui.tree.tiles.get_mut(max_id) {
            let title = for_all_tabs!(pane, t, t.title());
            drop(pane); // Release the mutable borrow

            let mut tab_viewer = MainTabViewer {
                app: app as *mut AppState,
                last_focused_id: std::ptr::null_mut(),
                last_maximized_id: maximized as *mut Option<TileId>,
            };
            Panel::top("maximized_top")
                .exact_size(24.0)
                .show_inside(ui, |ui| {
                    ui.horizontal(|ui| {
                        ui.label(title);
                        ui.label(RichText::new(tr!("menu-maximized-view")).italics());
                        if ui.button("x").clicked() {
                            *maximized = None;
                        }
                    });
                });
            // Re-borrow the pane for rendering
            if let Some(Tile::Pane(pane)) = app.main_ui.tree.tiles.get_mut(max_id) {
                let _ = tab_viewer.pane_ui(ui, max_id, pane);
            }
            return;
        }
    }
    let mut tab_viewer = MainTabViewer {
        app: app as *mut AppState,
        last_focused_id: &mut app.additional_ui.focused_id as *mut Option<TileId>,
        last_maximized_id: maximized as *mut Option<TileId>,
    };
    app.main_ui.tree.ui(&mut tab_viewer, ui);

}

pub fn show_ui(ui: &mut Ui, app: &mut AppState, cpu_time: Option<f32>) {
    // sync theme
    if app.preferences.dark_mode {
        ui.ctx().set_theme(egui::Theme::Dark);
    } else {
        ui.ctx().set_theme(egui::Theme::Light);
    }

