use egui::{Mesh, Painter, Rect, Shape, Stroke, pos2};
use serde::{Deserialize, Serialize};
use walkers::sources::{Attribution, OpenStreetMap, TileSource};
use walkers::{HttpTiles, Tile, TileId, Tiles, mercator};

use super::GraphNavigation;

#[derive(Default, Clone, Copy, Serialize, Deserialize, PartialEq)]
pub(crate) enum UnderlayTileType {
    None,
    #[default]
    OpenStreetMap,
    EsriWorldImagery,
}

/// Simplified underlay: draw world grid and optional OSM tiles.
pub(crate) fn draw_underlay(
    painter: &mut Painter,
    navi: &GraphNavigation,
    ui: &egui::Ui,
    new_type: Option<UnderlayTileType>,
) -> Option<Attribution> {
    draw_world_grid(
        painter,
        navi.visible,
        navi.offset_x() as f32,
        navi.offset_y() as f32,
        navi.zoom_x(),
    );

    new_type?; // if None, skip tiles (return None for attribution)
    // For now, return None attribution (tile loading requires more setup)
    None
}

fn draw_world_grid(painter: &Painter, viewport: Rect, offset_x: f32, offset_y: f32, zoom: f32) {
    if zoom <= 0.0 { return; }
    const MIN_WIDTH: f32 = 32.0;
    const MAX_WIDTH: f32 = 120.0;
    let base_color = egui::Color32::from_gray(160);

