// Handle selected coordinate (new station creation)
if let SelectedItems::Coordinate(coord_sel) = &mut app.selected_items {
    let screen_pos = tab.navi.xy_to_screen_pos(coord_sel.pos.lon as f64, coord_sel.pos.lat as f64);
    let rect = Rect::from_pos(screen_pos).expand(6.0);
    painter.rect(
        rect,
        0,
        Color32::RED.gamma_multiply(0.5),
        Stroke::new(1.0, Color32::RED),
        egui::StrokeKind::Middle,
    );
    let res = ui
        .allocate_rect(rect, Sense::drag())
        .on_hover_cursor(CursorIcon::Grab);
    if res.dragged() {
        let new_screen_pos = screen_pos + res.drag_delta();
        let (x, y) = tab.navi.screen_pos_to_xy(new_screen_pos);
        coord_sel.pos = LonLat { lon: x as i32, lat: y as i32 };
    }
    Popup::menu(&res)
        .open(true)
        .close_behavior(PopupCloseBehavior::CloseOnClickOutside)
        .show(|ui| {
            ui.set_width(200.0);
            ui.text_edit_singleline(&mut coord_sel.name_candidate);
            if ui.button(tr!("graph-new-station")).clicked() {
                let key = StationKey::new();
                let name: ecow::EcoString = coord_sel.name_candidate.clone().into();
                app.source.apply_command(Command::AddStation {
                    key,
                    name: if name.is_empty() { "New Station".into() } else { name },
                    pos: coord_sel.pos,
                });
                app.selected_items = SelectedItems::None;
            }
        });
}

