                    let key = StationKey::new();
                    app.source.apply_command(Command::AddStation {
                        key,
                        name: if name.is_empty() { "New Station".into() } else { name.into() },
                        pos: pos_copy,
                    });
                    app.selected_items = SelectedItems::None;
                }
            });
    }
}

